window.TADABBUR_NAJM = {"_meta":{"description":"تدبّر سورة النجم (٥٣)، وسورةٌ مكّيّةٌ، فيها أوّلُ سجدةِ تلاوةٍ في المصحف. محورُها إثباتُ صدقِ الوحيِ وأنّ النبيَّ لا ينطق عن الهوى، ورؤيتُه جبريلَ والمعراج، وإبطالُ عبادةِ الأصنامِ (اللاتِ والعزّى ومناة)، وأنّ الملائكةَ لا تُنسَب أنوثةً، ومبادئُ صحفِ إبراهيمَ وموسى (لا تزر وازرةٌ وزرَ أخرى، وليس للإنسانِ إلا ما سعى)، وأفعالُ الله وحده، وإهلاكُ الأمم، والأمرُ بالسجودِ والعبادة. فيها «وما ينطق عن الهوى إن هو إلا وحي يوحى»، و«وأن ليس للإنسان إلا ما سعى»، و«فبأي آلاء ربك تتمارى»، و«فاسجدوا لله واعبدوا».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":53,"name":"النجم","total_ayahs":62,"audio":[1,4,19,23,26,32,39,45,56,62],"passages":[{"title":"صدقُ الوحيِ ورؤيةُ النبيِّ لجبريل","range":[1,10],"theme":"القسمُ بالنجمِ على أنّ النبيَّ ما ضلَّ وما غوى وما ينطق عن الهوى إن هو إلا وحيٌ يوحى، علّمه جبريلُ شديدُ القوى، ودنا منه فتدلّى فكان قابَ قوسين أو أدنى فأوحى إلى عبدِه ما أوحى","verses":[{"n":1,"reflection":{"text":"«والنجم إذا هوى»: أقسم الله بالنجمِ إذا سقط وغاب، أو بالثريّا، أو بالقرآنِ إذا نزل؛ ففي هذا قسمٌ بآيةٍ من آياتِ الله؛ فعظّم آياتِ الله التي أقسم بها، فالنجومُ آياتٌ دالّةٌ على قدرةِ الله، فاعتبر بها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ آياتِ الله، والاعتبارُ بالنجومِ آيةً على قدرته."},"action":{"text":"تأمّل قسمَ الله بالنجم: أقسم الله بالنجمِ إذا هوى، أي سقط وغاب عند غروبه، أو بالثريّا إذا سقطت، أو بنجومِ القرآنِ إذا نزلت مفرّقة «والنجم إذا هوى»؛ ففي هذا قسمٌ من الله بالنجمِ لعظمته ودلالته على قدرته؛ فأقسم به آيةً من آياته؛ فعظّم أنت آياتِ الله التي أقسم بها؛ فالنجومُ آياتٌ عظيمةٌ دالّةٌ على قدرةِ الله وحكمته؛ وهو الذي جعل لكم النجومَ لتهتدوا بها في ظلماتِ البرِّ والبحر؛ وزيّنّا السماءَ الدنيا بمصابيح؛ فالنجومُ زينةٌ وهدايةٌ ورجومٌ للشياطين؛ فاعتبر بالنجومِ آيةً على قدرةِ الله ووحدانيته؛ فمن تفكّر في آياتِ الله اهتدى وأيقن؛ فاجعل تعظيمَ آياتِ الله والاعتبارَ بها دأبك."}},{"n":2,"reflection":{"text":"«ما ضل صاحبكم وما غوى»: ما ضلَّ محمدٌ صاحبكم عن الحقِّ وما غوى بالباطل؛ ففي هذا تزكيةُ النبيِّ وبراءتُه من الضلال؛ فاعلم أنّ النبيَّ على الهدى والحقّ، فاتّبعه واثق بهديه، فهو المهتدي الهادي لا الضالّ الغاوي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بهدي النبيِّ واتّباعُه، وإدراكُ أنه على الحق."},"action":{"text":"تأمّل تزكيةَ النبيّ: هذا جوابُ القسم: ما ضلَّ صاحبكم، وهو محمدٌ ﷺ الذي تعرفونه، عن طريقِ الحقِّ والهدى، وما غوى، أي ما اتّبع الباطلَ والضلال؛ بل هو على الهدى والحقِّ التام «ما ضل صاحبكم وما غوى»؛ ففي هذا تزكيةُ الله لنبيّه وبراءتُه من الضلالِ والغِواية؛ فنفى عنه الضلالَ (وهو الجهلُ بالحق) والغِواية (وهي اتّباعُ الباطلِ مع العلم)؛ فهو على كمالِ الهدى علمًا وعملًا؛ فاعلم أنت أنّ النبيَّ ﷺ على الهدى والحقِّ التام، لا ضلالَ فيه ولا غِواية؛ وإنك لتهدي إلى صراطٍ مستقيم؛ وإنك لعلى خلقٍ عظيم؛ ما ضلَّ صاحبكم وما غوى؛ فاتّبعه أنت وثق بهديه؛ فهو المهتدي الهادي إلى الصراطِ المستقيم؛ فمن اتّبع النبيَّ اهتدى، ومن أعرض عنه ضلّ؛ فاجعل الثقةَ بهدي النبيِّ واتّباعَه دأبك."}},{"n":3,"reflection":{"text":"«وما ينطق عن الهوى»، وما ينطق محمدٌ عن هوى نفسه فيما يبلّغه عن الله؛ ففي هذا بيانُ عصمةِ النبيِّ فيما يبلّغ؛ فاعلم أنّ ما نطق به النبيُّ من الوحيِ حقٌّ لا هوى فيه، فاتّبع سنّته كوحيٍ من الله، فالنبيُّ لا ينطق عن هوى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ سنّةِ النبيِّ كوحي، وإدراكُ أنه لا ينطق عن هوى."},"action":{"text":"تأمّل عصمةَ النبيِّ فيما يبلّغ: وما ينطق محمدٌ ﷺ عن الهوى، أي عن هوى نفسه ورغبتها، فيما يبلّغه عن الله من الوحيِ والقرآنِ والسنّة؛ فليس ما يقوله في الدينِ عن هوًى، بل عن وحي «وما ينطق عن الهوى»؛ ففي هذا بيانُ عصمةِ النبيِّ ﷺ فيما يبلّغه عن الله، وأنه لا ينطق فيه عن هوى؛ فكلُّ ما يبلّغه عن الله حقٌّ لا هوى فيه؛ فاعلم أنت أنّ ما نطق به النبيُّ ﷺ من القرآنِ والسنّةِ حقٌّ ووحيٌ لا هوى فيه؛ فاتّبع سنّته وأقواله كوحيٍ من الله؛ وما آتاكم الرسولُ فخذوه وما نهاكم عنه فانتهوا؛ من يطعِ الرسولَ فقد أطاع الله؛ فالنبيُّ لا ينطق في الدينِ عن هوى، بل عن وحي؛ فسنّته وحيٌ يجب اتّباعه؛ فمن اتّبع سنّةَ النبيِّ اهتدى، ومن ردّها ضلّ؛ فاجعل اتّباعَ سنّةِ النبيِّ كوحيٍ من الله دأبك."}},{"n":4,"reflection":{"text":"«إن هو إلا وحي يوحى»: ما القرآنُ (أو ما ينطق به) إلا وحيٌ يُوحى إليه من الله؛ ففي هذا تقريرُ أنّ القرآنَ والسنّةَ وحيٌ من الله؛ فعظّم القرآنَ والسنّةَ فإنهما وحيٌ من الله، فاتّبعهما ولا تقدّم عليهما شيئًا، فالوحيُ حجّةٌ قاطعة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الوحي (القرآنِ والسنّة) واتّباعُه دون تقديمِ شيءٍ عليه."},"action":{"text":"تأمّل تقريرَ أنّ القرآنَ وحي: إن هو، أي القرآنُ وما ينطق به النبيُّ في الدين، إلا وحيٌ يُوحى إليه من الله بواسطةِ جبريل؛ فليس من عند نفسه، بل من عند الله «إن هو إلا وحي يوحى»؛ ففي هذا تقريرُ أنّ القرآنَ وما يبلّغه النبيُّ من السنّةِ وحيٌ من الله؛ فمصدره الوحيُ لا الهوى؛ فعظّم أنت القرآنَ والسنّةَ فإنهما وحيٌ من الله؛ تنزيلٌ من حكيمٍ حميد؛ وأوحينا إليك هذا القرآن؛ وما ينطق عن الهوى إن هو إلا وحيٌ يوحى؛ فاتّبع الوحيَ (الكتابَ والسنّة) ولا تقدّم عليه رأيًا ولا هوًى ولا قولَ أحد؛ اتّبعوا ما أُنزِل إليكم من ربّكم؛ فالوحيُ حجّةٌ قاطعةٌ يجب اتّباعها؛ فمن اتّبع الوحيَ وعظّمه اهتدى، ومن قدّم عليه غيره ضلّ؛ فاجعل تعظيمَ الوحيِ واتّباعَه دون تقديمِ شيءٍ عليه دأبك."}},{"n":5,"reflection":{"text":"«علمه شديد القوى»: علّم محمدًا الوحيَ مَلَكٌ شديدُ القوى (جبريل)؛ ففي هذا بيانُ واسطةِ الوحي؛ فاعلم أنّ الوحيَ جاء عبر جبريلَ الأمينِ القويّ، فثق بأمانةِ الوحيِ ونقله، فالوحيُ نقله أمينٌ قويّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأمانةِ الوحيِ ونقله عبر جبريلَ القويّ."},"action":{"text":"تأمّل واسطةَ الوحي: علّم محمدًا ﷺ الوحيَ والقرآنَ مَلَكٌ شديدُ القوى، وهو جبريلُ عليه السلام، ذو القوّةِ العظيمةِ في تنفيذِ أمرِ الله «علمه شديد القوى»؛ ففي هذا بيانُ أنّ الذي علّم النبيَّ الوحيَ هو جبريلُ الملَكُ شديدُ القوى؛ فالوحيُ جاء عبر جبريلَ الأمينِ القويّ؛ فاعلم أنت أنّ الوحيَ نزل به جبريلُ الأمينُ القويُّ على قلبِ النبيّ؛ نزل به الروحُ الأمين، على قلبك لتكون من المنذرين؛ ذي قوّةٍ عند ذي العرشِ مكين، مطاعٍ ثمّ أمين؛ فثق أنت بأمانةِ الوحيِ ونقله، فقد نقله أمينٌ قويٌّ عن الله؛ فالوحيُ محفوظٌ في نزوله وبلاغه؛ فمن وثق بأمانةِ الوحيِ آمن به واتّبعه؛ فاجعل الثقةَ بأمانةِ الوحيِ ونقله دأبك."}},{"n":6,"reflection":{"text":"«ذو مرة فاستوى»: جبريلُ ذو قوّةٍ ومنظرٍ حسن، فاستوى واستقام على صورتِه الحقيقية؛ ففي هذا بيانُ عظمةِ خلقِ جبريل؛ فتأمّل عظمةَ خلقِ جبريلَ من ملائكةِ الله، فمن خلقه بهذه العظمةِ عظيمُ القدرة، فعظّم خالقَ الملائكة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ خالقِ الملائكةِ العظيمة، والتفكّرُ في خلقِ جبريل."},"action":{"text":"تأمّل عظمةَ خلقِ جبريل: جبريلُ ذو مرّةٍ، أي ذو قوّةٍ شديدة، وخَلقٍ حسنٍ ومنظرٍ بهيّ؛ فاستوى واستقام على صورتِه الحقيقيةِ التي خلقه الله عليها، وله ستّمائةِ جناح «ذو مرة فاستوى»؛ ففي هذا بيانُ عظمةِ خلقِ جبريلَ وقوّته وحسنِ منظره، واستوائه على صورته؛ فهو ملَكٌ عظيمُ الخلقِ قويٌّ حسن؛ فتأمّل أنت عظمةَ خلقِ جبريلَ من ملائكةِ الله العظام؛ رأى جبريلَ في صورتِه له ستّمائةِ جناح، قد سدَّ الأفق؛ فاطرًا للسماواتِ والأرضِ جاعلِ الملائكةِ رسلًا أولي أجنحةٍ مثنى وثلاثَ ورباع؛ فمن خلق جبريلَ والملائكةَ بهذه العظمةِ عظيمُ القدرةِ والخلق؛ فعظّم أنت خالقَ الملائكةِ العظيمة؛ فمن تفكّر في عظمةِ خلقِ الله عظّم الخالقَ؛ فاجعل تعظيمَ خالقِ الملائكةِ والتفكّرَ في خلقه دأبك."}},{"n":7,"reflection":{"text":"«وهو بالأفق الأعلى»، وجبريلُ بالأفقِ الأعلى (مطلعِ الشمس) حين رآه النبيُّ على صورته؛ ففي هذا بيانُ مكانِ رؤيةِ النبيِّ لجبريل؛ فاعلم أنّ النبيَّ رأى جبريلَ حقًّا، فصدّق بما أخبر به النبيُّ من رؤيته، فرؤيةُ النبيِّ لجبريلَ حق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ بما أخبر به النبيُّ من رؤيةِ جبريل."},"action":{"text":"تأمّل مكانَ الرؤية: وجبريلُ بالأفقِ الأعلى، أي في ناحيةِ المشرقِ الأعلى من السماء، حيث رآه النبيُّ ﷺ على صورتِه الحقيقيةِ سادًّا الأفق «وهو بالأفق الأعلى»؛ ففي هذا بيانُ أنّ النبيَّ ﷺ رأى جبريلَ على صورته في الأفقِ الأعلى؛ فرآه حقًّا في هذا المكانِ العالي؛ فاعلم أنت أنّ النبيَّ ﷺ رأى جبريلَ على صورته الحقيقيةِ مرّتين؛ ولقد رآه بالأفقِ المبين؛ فصدّق بما أخبر به النبيُّ ﷺ من رؤيته لجبريل؛ فما أخبر به النبيُّ حقٌّ لا كذبَ فيه، فهو لا ينطق عن الهوى؛ فرؤيةُ النبيِّ لجبريلَ على صورته حقٌّ ثابت؛ فمن صدّق بما أخبر به النبيُّ آمن، ومن كذّب به كفر؛ فاجعل التصديقَ بما أخبر به النبيُّ من رؤيةِ جبريلَ دأبك."}},{"n":8,"reflection":{"text":"«ثم دنا فتدلى»: ثم قرُب جبريلُ من النبيِّ فزاد في القربِ ونزل؛ ففي هذا بيانُ قربِ جبريلَ من النبيّ؛ فاعلم أنّ الله أكرم نبيّه بقربِ جبريلَ منه لتبليغِ الوحي، فعظّم منزلةَ النبيِّ عند الله، فقربُ الوحيِ منه كرامةٌ له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ منزلةِ النبيِّ عند الله، وإدراكُ كرامةِ الوحيِ له."},"action":{"text":"تأمّل قربَ جبريل: ثم دنا جبريلُ وقرُب من النبيِّ ﷺ، فتدلّى، أي زاد في القربِ والدنوِّ، ونزل نحوه؛ فقرُب منه غايةَ القرب لتبليغِ الوحي «ثم دنا فتدلى»؛ ففي هذا بيانُ قربِ جبريلَ من النبيِّ ﷺ ودنوّه منه؛ فقرُب منه لتبليغِ الوحيِ وتأكيدِ الرسالة؛ فاعلم أنت أنّ الله أكرم نبيّه ﷺ بقربِ جبريلَ منه ومباشرتِه بالوحي؛ فعظّم منزلةَ النبيِّ ﷺ عند الله، حيث أكرمه بهذا القرب؛ فقربُ الوحيِ وجبريلَ من النبيِّ كرامةٌ عظيمةٌ له؛ فمن عظّم منزلةَ النبيِّ عند الله وقّره واتّبعه؛ فاجعل تعظيمَ منزلةِ النبيِّ عند الله دأبك."}},{"n":9,"reflection":{"text":"«فكان قاب قوسين أو أدنى»: فكان جبريلُ من النبيِّ قدرَ قوسين أو أقربَ من ذلك؛ ففي هذا بيانُ شدّةِ قربِ جبريلَ من النبيّ؛ فاعلم أنّ الله أدنى جبريلَ من نبيّه غايةَ الدنوِّ لتبليغِ الوحي، فعظّم شأنَ الوحيِ وبلاغه، فقربُ جبريلَ تأكيدٌ للوحي.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ شأنِ الوحيِ وبلاغه، وإدراكُ عنايةِ الله بتبليغه."},"action":{"text":"تأمّل شدّةَ القرب: فكان جبريلُ من النبيِّ ﷺ قابَ قوسين، أي قدرَ قوسين عربيّتين، أو أدنى وأقربَ من ذلك؛ فبلغ غايةَ القربِ منه لتبليغِ الوحيِ ومباشرتِه «فكان قاب قوسين أو أدنى»؛ ففي هذا بيانُ شدّةِ قربِ جبريلَ من النبيِّ ﷺ حال تبليغِ الوحي؛ فقرُب منه غايةَ القربِ حتى صار قدرَ قوسين أو أقرب؛ فاعلم أنت أنّ الله أدنى جبريلَ من نبيّه غايةَ الدنوِّ اهتمامًا بتبليغِ الوحيِ وتأكيده؛ فعظّم شأنَ الوحيِ وبلاغه وعنايةِ الله به؛ فقربُ جبريلَ من النبيِّ تأكيدٌ للوحيِ ومباشرةٌ في تبليغه؛ فهذا يدلّ على عظمةِ ما نزل به من الوحي؛ فمن عظّم شأنَ الوحيِ وعنايةَ الله بتبليغه عظّمه واتّبعه؛ فاجعل تعظيمَ شأنِ الوحيِ وبلاغه دأبك."}},{"n":10,"reflection":{"text":"«فأوحى إلى عبده ما أوحى»: فأوحى الله (بواسطةِ جبريل) إلى عبدِه محمدٍ ما أوحى من الوحيِ العظيم؛ ففي هذا تعظيمُ شأنِ الوحي؛ فعظّم الوحيَ الذي أوحاه الله إلى نبيّه، وتأمّل شرفَ العبوديةِ التي وُصِف بها النبيُّ في أعلى مقاماته، فأشرفُ مقاماتِ العبدِ عبوديّتُه لله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الوحي، وإدراكُ شرفِ العبوديةِ لله في أعلى المقامات."},"action":{"text":"تأمّل تعظيمَ شأنِ الوحي: فأوحى الله سبحانه، بواسطةِ جبريلَ، إلى عبدِه محمدٍ ﷺ ما أوحى من الوحيِ العظيمِ الجليل؛ فأبهم ما أوحى تفخيمًا وتعظيمًا لشأنه «فأوحى إلى عبده ما أوحى»؛ ففي هذا تعظيمُ شأنِ الوحيِ الذي أوحاه الله إلى نبيّه؛ فأبهمه تعظيمًا وتفخيمًا؛ ولاحظ وصفَ النبيِّ بالعبوديةِ (عبده) في هذا المقامِ الأعلى؛ فأشرفُ أوصافِ النبيِّ عبوديّتُه لله؛ فعظّم أنت الوحيَ الذي أوحاه الله إلى نبيّه؛ وتأمّل شرفَ العبوديةِ التي وُصِف بها النبيُّ في أعلى مقاماته (المعراجِ والوحي)؛ سبحان الذي أسرى بعبده؛ وأنه لمّا قام عبدُ الله يدعوه؛ فأشرفُ مقاماتِ العبدِ ولايتُه لله بالعبودية؛ فمن حقّق العبوديةَ لله شرُف، ومن غفل عنها هان؛ فاجعل تعظيمَ الوحيِ وتحقيقَ العبوديةِ لله دأبك."}}]},{"title":"رؤيةُ الآياتِ الكبرى عند سدرةِ المنتهى","range":[11,18],"theme":"تأكيدُ أنّ فؤادَ النبيِّ لم يكذب ما رأى فلا يُمارى فيه، وأنه رأى جبريلَ نزلةً أخرى عند سدرةِ المنتهى عندها جنّةُ المأوى إذ يغشى السدرةَ ما يغشى، ما زاغ البصرُ وما طغى لقد رأى من آياتِ ربّه الكبرى","verses":[{"n":11,"reflection":{"text":"«ما كذب الفؤاد ما رأى»: ما كذب قلبُ النبيِّ ما رأته عينه (من جبريلَ أو الآيات)؛ ففي هذا تأكيدُ صدقِ رؤيةِ النبيّ؛ فصدّق بما رآه النبيُّ وأخبر به، فقلبُ النبيِّ وبصره صادقان، فما أخبر به النبيُّ عن رؤيته حق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ بما رآه النبيُّ وأخبر به، وإدراكُ صدقِ قلبه."},"action":{"text":"تأمّل تأكيدَ صدقِ الرؤية: ما كذب فؤادُ النبيِّ ﷺ وقلبه ما رأته عينه من جبريلَ على صورته، أو من آياتِ ربّه؛ بل صدّق القلبُ ما رأى البصر، فوافق القلبُ البصر في الصدق «ما كذب الفؤاد ما رأى»؛ ففي هذا تأكيدُ صدقِ رؤيةِ النبيِّ ﷺ، وأنّ قلبه صدّق ما رأته عينه، فلا وهمَ ولا خطأ؛ فما رآه حقٌّ ثابت؛ فصدّق أنت بما رآه النبيُّ ﷺ وأخبر به من رؤيةِ جبريلَ وآياتِ ربّه؛ فقلبُ النبيِّ وبصره صادقان معصومان من الخطأ فيما رأى؛ لقد رأى من آياتِ ربّه الكبرى؛ ما زاغ البصرُ وما طغى؛ فما أخبر به النبيُّ عن رؤيته حقٌّ لا كذبَ فيه ولا وهم؛ فمن صدّق بما أخبر به النبيُّ آمن، ومن كذّب به ضلّ؛ فاجعل التصديقَ بما رآه النبيُّ وأخبر به دأبك."}},{"n":12,"reflection":{"text":"«أفتمارونه على ما يرى»: أفتجادلون النبيَّ وتكذّبونه على ما يراه من الآيات؟ ففي هذا إنكارٌ على من يجادل النبيَّ في رؤيته؛ فلا تجادل في الحقِّ الذي أخبر به النبيُّ، بل صدّق به، فمجادلةُ النبيِّ في الحقِّ من صفاتِ المكذّبين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ بالحقِّ الذي أخبر به النبيُّ، وتركُ المجادلةِ فيه."},"action":{"text":"تأمّل الإنكارَ على المجادلين: أفتمارونه، أي أفتجادلون محمدًا ﷺ وتكذّبونه وتشكّكونه، على ما يراه من الآياتِ والوحي؟ إنكارٌ عليهم في مجادلتهم للنبيِّ فيما رآه وأخبر به «أفتمارونه على ما يرى»؛ ففي هذا إنكارٌ على المشركين الذين يجادلون النبيَّ ويكذّبونه فيما رآه من الآيات؛ فأنكر عليهم مجادلتهم وتكذيبهم؛ فلا تجادل أنت في الحقِّ الذي أخبر به النبيُّ ﷺ من رؤيةِ الآياتِ والوحي؛ بل صدّق به واقبله؛ فمجادلةُ النبيِّ وتكذيبه فيما أخبر به من صفاتِ المكذّبين المعاندين؛ ما يجادل في آياتِ الله إلا الذين كفروا؛ فما أخبر به النبيُّ حقٌّ لا يُجادَل فيه؛ فمن صدّق بما أخبر به النبيُّ اهتدى، ومن جادل فيه وكذّبه ضلّ؛ فاجعل التصديقَ بالحقِّ الذي أخبر به النبيُّ وتركَ المجادلةِ فيه دأبك."}},{"n":13,"reflection":{"text":"«ولقد رآه نزلة أخرى»، ولقد رأى النبيُّ جبريلَ نزلةً أخرى (مرّةً ثانية) على صورته؛ ففي هذا تأكيدُ رؤيةِ النبيِّ لجبريل؛ فاعلم أنّ النبيَّ رأى جبريلَ مرّتين على صورته، فصدّق بهذه الكرامةِ للنبيّ، فرؤيتُه لجبريلَ مرّتين حقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ برؤيةِ النبيِّ لجبريلَ مرّتين، وتعظيمُ كرامته."},"action":{"text":"تأمّل تأكيدَ الرؤية: ولقد رأى النبيُّ ﷺ جبريلَ على صورتِه الحقيقيةِ نزلةً أخرى، أي مرّةً ثانيةً، في ليلةِ المعراج؛ فرآه مرّتين على صورته «ولقد رآه نزلة أخرى»؛ ففي هذا تأكيدُ أنّ النبيَّ ﷺ رأى جبريلَ على صورته الحقيقيةِ مرّتين: مرّةً في الأفق، ومرّةً عند سدرةِ المنتهى؛ فرآه حقًّا مرّتين؛ فاعلم أنت أنّ النبيَّ ﷺ رأى جبريلَ على صورته العظيمةِ مرّتين، إكرامًا له؛ فصدّق بهذه الكرامةِ العظيمةِ للنبيّ؛ فرؤيتُه لجبريلَ على صورته حقٌّ ثابت؛ ولقد رآه بالأفقِ المبين؛ فمن صدّق بما أخبر به النبيُّ من رؤيته آمن؛ فاجعل التصديقَ برؤيةِ النبيِّ لجبريلَ وتعظيمَ كرامتِه دأبك."}},{"n":14,"reflection":{"text":"«عند سدرة المنتهى»: رآه عند سدرةِ المنتهى (شجرةٍ في السماءِ السابعةِ إليها ينتهي علمُ الخلق)؛ ففي هذا بيانُ مكانِ الرؤيةِ العظيم؛ فعظّم شأنَ المعراجِ الذي بلغ فيه النبيُّ هذا المقامَ العظيم، فمقامُ النبيِّ عند الله عظيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ شأنِ المعراجِ ومقامِ النبيِّ عند الله."},"action":{"text":"تأمّل مكانَ الرؤية: رأى النبيُّ ﷺ جبريلَ عند سدرةِ المنتهى، وهي شجرةُ نبقٍ عظيمةٌ في السماءِ السابعة (أو السادسة)، إليها ينتهي ما يعرج من الأرضِ وما ينزل من فوقها، وإليها ينتهي علمُ الخلائق «عند سدرة المنتهى»؛ ففي هذا بيانُ مكانِ رؤيةِ النبيِّ لجبريلَ في المعراج، عند سدرةِ المنتهى العظيمة؛ فبلغ النبيُّ هذا المقامَ العظيمَ الذي لم يبلغه أحد؛ فعظّم أنت شأنَ المعراجِ الذي أُسرِي فيه بالنبيِّ وعُرِج به إلى هذا المقامِ العظيم؛ سبحان الذي أسرى بعبده ليلًا من المسجدِ الحرام إلى المسجدِ الأقصى؛ فمقامُ النبيِّ ﷺ عند الله عظيمٌ رفيع؛ فمن عظّم مقامَ النبيِّ عند الله وقّره واتّبعه؛ فاجعل تعظيمَ شأنِ المعراجِ ومقامِ النبيِّ عند الله دأبك."}},{"n":15,"reflection":{"text":"«عندها جنة المأوى»: عند سدرةِ المنتهى جنّةُ المأوى (التي يأوي إليها المؤمنون والشهداء)؛ ففي هذا بيانُ قربِ الجنّةِ من ذلك المقام؛ فاطلب جنّةَ المأوى بالإيمانِ والعمل، فالجنّةُ مأوى المؤمنين، فاعمل لتأوي إليها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لجنّةِ المأوى بالإيمانِ والعمل."},"action":{"text":"تأمّل موضعَ الجنّة: عند سدرةِ المنتهى جنّةُ المأوى، وهي الجنّةُ التي يأوي إليها المؤمنون والمتّقون والشهداء، ومأوى أرواحِ الشهداء «عندها جنة المأوى»؛ ففي هذا بيانُ أنّ جنّةَ المأوى عند سدرةِ المنتهى، حيث رأى النبيُّ من آياتِ ربّه؛ فالجنّةُ قريبةٌ من ذلك المقامِ العظيم؛ فاطلب أنت جنّةَ المأوى بالإيمانِ والتقوى والعملِ الصالح؛ فالجنّةُ مأوى المؤمنين المتّقين؛ فأمّا من طغى وآثر الحياةَ الدنيا فإنّ الجحيمَ هي المأوى، وأمّا من خاف مقامَ ربّه ونهى النفسَ عن الهوى فإنّ الجنّةَ هي المأوى؛ ومأواهم الجنّةُ بما كانوا يعملون؛ فاعمل لتأوي إلى جنّةِ المأوى؛ فمن آمن وعمل صالحًا أوى إليها، ومن كفر وطغى أوى إلى النار؛ فاجعل العملَ لجنّةِ المأوى بالإيمانِ والعملِ دأبك."}},{"n":16,"reflection":{"text":"«إذ يغشى السدرة ما يغشى»: حين يغشى سدرةَ المنتهى من أمرِ الله ونوره وجمالِه ما يغشى؛ ففي هذا تعظيمُ ما رآه النبيُّ من آياتِ الله؛ فعظّم آياتِ الله العظيمةَ التي رآها النبيّ، فآياتُ الله في ذلك المقامِ عظيمةٌ لا تُحَدّ، فسبّح خالقها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ آياتِ الله العظيمة، وتسبيحُ خالقها."},"action":{"text":"تأمّل تعظيمَ ما غشي السدرة: اذكر حين يغشى سدرةَ المنتهى من أمرِ الله وعظمته، ومن نورٍ وبهاءٍ وجمالٍ وملائكةٍ وفراشٍ من ذهب، ما يغشاها ممّا لا يقدر أحدٌ على وصفه؛ فأبهمه تعظيمًا لشأنه «إذ يغشى السدرة ما يغشى»؛ ففي هذا تعظيمُ ما رآه النبيُّ ﷺ عند سدرةِ المنتهى من آياتِ الله العظيمةِ التي غشيتها؛ فأبهمها تفخيمًا وتعظيمًا لعظمتها؛ فعظّم أنت آياتِ الله العظيمةَ التي رآها النبيُّ في ذلك المقام؛ فآياتُ الله في ذلك المقامِ عظيمةٌ لا تُحَدُّ ولا تُوصَف؛ لقد رأى من آياتِ ربّه الكبرى؛ فسبّح خالقَ تلك الآياتِ العظيمةَ ونزّهه؛ سبحان ربّك ربِّ العزّةِ عمّا يصفون؛ فمن عظّم آياتِ الله سبّح خالقها وأيقن بعظمته؛ فاجعل تعظيمَ آياتِ الله العظيمةِ وتسبيحَ خالقها دأبك."}},{"n":17,"reflection":{"text":"«ما زاغ البصر وما طغى»: ما مال بصرُ النبيِّ عمّا رأى ولا تجاوزه؛ ففي هذا بيانُ كمالِ أدبِ النبيِّ في الرؤية؛ فاقتدِ بأدبِ النبيِّ في ثباتِ بصره وعدمِ تجاوزه، فالأدبُ مع الله في أعلى المقاماتِ من كمالِ العبودية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بأدبِ النبيِّ، وإدراكُ أنّ الأدبَ مع الله كمالُ العبودية."},"action":{"text":"تأمّل كمالَ أدبِ النبيّ: ما زاغ بصرُ النبيِّ ﷺ يمينًا ولا شمالًا عمّا أُمِر برؤيته، وما طغى وما تجاوز ما رآه إلى غيره؛ بل ثبت بصره على ما أُرِيه بأدبٍ كامل «ما زاغ البصر وما طغى»؛ ففي هذا بيانُ كمالِ أدبِ النبيِّ ﷺ في تلك الرؤيةِ العظيمة، حيث لم يلتفت بصره ولم يتجاوز؛ فحفظ بصره وأدبه في أعلى المقامات؛ فاقتدِ أنت بأدبِ النبيِّ ﷺ في ثباتِ بصره وعدمِ تجاوزه وحفظِ أدبه مع الله؛ فالأدبُ مع الله في كلِّ المقاماتِ من كمالِ العبودية؛ فكان النبيُّ في أعلى مقاماته أكملَ أدبًا؛ يا أيها الذين آمنوا لا ترفعوا أصواتكم فوق صوتِ النبيّ؛ فالأدبُ مع الله ومع الوحيِ من كمالِ الإيمان؛ فمن تأدّب مع الله ووحيه كمُلت عبوديّته؛ فاجعل الاقتداءَ بأدبِ النبيِّ وحفظَ الأدبِ مع الله دأبك."}},{"n":18,"reflection":{"text":"«لقد رأى من آيات ربه الكبرى»: لقد رأى النبيُّ من آياتِ ربّه العظمى في المعراج؛ ففي هذا تقريرُ أنّ النبيَّ رأى الآياتِ الكبرى؛ فصدّق بما رآه النبيُّ من آياتِ الله الكبرى، وعظّم قدرةَ الله التي أظهرها لنبيّه، فآياتُ الله الكبرى دليلُ عظمته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التصديقُ برؤيةِ النبيِّ لآياتِ الله الكبرى، وتعظيمُ قدرته."},"action":{"text":"تأمّل رؤيةَ الآياتِ الكبرى: لقد رأى النبيُّ ﷺ في تلك الليلةِ من آياتِ ربّه الكبرى العظمى: من عجائبِ الملكوت، وجبريلَ على صورته، والجنّة، والسدرة، وغيرها من الآياتِ العظيمةِ الدالّةِ على قدرةِ الله «لقد رأى من آيات ربه الكبرى»؛ ففي هذا تقريرُ أنّ النبيَّ ﷺ رأى في المعراجِ آياتِ ربّه الكبرى العظمى؛ فأراه الله من آياته الكبرى؛ فصدّق أنت بما رآه النبيُّ ﷺ من آياتِ الله الكبرى في المعراج؛ لنريه من آياتنا؛ سبحان الذي أسرى بعبده... لنريه من آياتنا إنه هو السميعُ البصير؛ وعظّم قدرةَ الله العظيمةَ التي أظهرها لنبيّه؛ فآياتُ الله الكبرى دليلُ عظمته وقدرته؛ فمن صدّق بآياتِ الله وعظّم قدرته آمن وأيقن؛ فاجعل التصديقَ برؤيةِ النبيِّ لآياتِ الله الكبرى وتعظيمَ قدرته دأبك."}}]},{"title":"إبطالُ الأصنامِ ونسبةِ البناتِ لله","range":[19,25],"theme":"إبطالُ عبادةِ اللاتِ والعزّى ومناة، وأنّ نسبتهم الذكرَ لأنفسهم والأنثى لله قسمةٌ ضيزى، وأنّ الأصنامَ أسماءٌ سمّوها بلا سلطانٍ يتّبعون الظنَّ والهوى وقد جاءهم الهدى، وأنه ليس للإنسانِ ما تمنّى فلله الآخرةُ والأولى","verses":[{"n":19,"reflection":{"text":"«أفرأيتم اللات والعزى»: أخبروني عن اللاتِ والعزّى (صنمين للمشركين)؛ ففي هذا بدءُ إبطالِ عبادةِ الأصنام؛ فاعلم أنّ الأصنامَ لا تنفع ولا تضرّ، فكيف تُعبَد؟ فوحّد الله ولا تعبد صنمًا، فعبادةُ الأصنامِ باطلةٌ لا حجّةَ لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله وتركُ عبادةِ الأصنام، وإدراكُ بطلانها."},"action":{"text":"تأمّل بدءَ إبطالِ الأصنام: أفرأيتم، أيها المشركون، وأخبروني عن اللاتِ والعزّى، وهما صنمان كان يعبدهما المشركون: اللاتُ بالطائف، والعزّى بنخلةَ قربَ مكّة «أفرأيتم اللات والعزى»؛ ففي هذا بدءُ إبطالِ عبادةِ الأصنامِ والاحتجاجِ على المشركين؛ فسألهم عن آلهتهم توبيخًا: ماذا تملك من نفعٍ أو ضرّ؟ فاعلم أنت أنّ الأصنامَ والأندادَ لا تنفع ولا تضرّ، ولا تخلق ولا ترزق؛ فكيف تُعبَد من دونِ الله؟ إنّ الذين تدعون من دونِ الله عبادٌ أمثالكم؛ أيشركون ما لا يخلق شيئًا وهم يُخلَقون؛ فوحّد أنت الله ولا تعبد صنمًا ولا ندًّا؛ فعبادةُ الأصنامِ باطلةٌ لا حجّةَ لها ولا دليل؛ فمن وحّد الله ونبذ الأصنامَ نجا، ومن عبدها هلك؛ فاجعل توحيدَ الله وتركَ عبادةِ الأصنامِ دأبك."}},{"n":20,"reflection":{"text":"«ومناة الثالثة الأخرى»، ومناةَ الصنمِ الثالثِ (للمشركين)؛ ففي هذا تتمّةُ ذكرِ أصنامهم؛ فاعلم أنّ هذه الأصنامَ الثلاثةَ مجرّدُ أحجارٍ لا تملك شيئًا، فلا تعبد ما لا يملك، فالأصنامُ عاجزةٌ لا تستحقّ العبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ عبادةِ ما لا يملك، وإدراكُ عجزِ الأصنام."},"action":{"text":"تأمّل تتمّةَ ذكرِ الأصنام: ومناةَ، وهو الصنمُ الثالثُ الأخير من أصنامهم الكبرى، كان لخزاعةَ والأوسِ والخزرجِ قربَ المدينة؛ فذكر أصنامهم الثلاثةَ الكبرى «ومناة الثالثة الأخرى»؛ ففي هذا تتمّةُ ذكرِ أصنامِ المشركين الثلاثةِ الكبرى، تمهيدًا لإبطالِ عبادتها؛ فهذه الأصنامُ الثلاثةُ (اللاتُ والعزّى ومناة) مجرّدُ أحجارٍ لا تملك شيئًا؛ فاعلم أنت أنّ هذه الأصنامَ عاجزةٌ لا تنفع ولا تضرّ ولا تسمع ولا تبصر؛ فلا تعبد ما لا يملك لنفسه ولا لغيره شيئًا؛ إن تدعوهم لا يسمعوا دعاءكم؛ ما لهم بذلك من علمٍ إن هم إلا يخرصون؛ فالأصنامُ عاجزةٌ حقيرةٌ لا تستحقّ العبادة؛ فمن ترك عبادةَ العاجزِ وعبد القادرَ نجا؛ فاجعل تركَ عبادةِ ما لا يملك وتوحيدَ القادرِ دأبك."}},{"n":21,"reflection":{"text":"«ألكم الذكر وله الأنثى»: أتجعلون لأنفسكم الذكورَ التي تحبّون، ولله الإناثَ التي تكرهون (بزعمهم أنّ الملائكةَ بناتُ الله)؟ ففي هذا إبطالُ نسبتهم البناتِ لله؛ فاحذر نسبةَ النقصِ إلى الله، ونزّهه عن الولدِ والبنات، فنسبةُ الباطلِ إلى الله ظلمٌ عظيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن النقص، والحذرُ من نسبةِ الباطلِ إليه."},"action":{"text":"تأمّل إبطالَ نسبتهم البنات: ألكم، أيها المشركون، الذكرُ الذي تحبّونه وتؤثرونه، ولله الأنثى التي تكرهونها وتئدونها (بزعمهم أنّ الملائكةَ والأصنامَ بناتُ الله)؟ فكيف تنسبون إليه ما تكرهون لأنفسكم؟ «ألكم الذكر وله الأنثى»؛ ففي هذا إبطالٌ لنسبةِ المشركين البناتِ إلى الله، وبيانُ تناقضهم وظلمهم؛ فنسبوا إليه ما يكرهون؛ فاحذر أنت نسبةَ النقصِ والولدِ والبناتِ إلى الله؛ ونزّهه عن الولدِ والصاحبةِ وكلِّ ما لا يليق به؛ وجعلوا له من عباده جزءًا؛ أم له البناتُ ولكم البنون؛ ويجعلون لله البناتِ سبحانه؛ ما اتّخذ الله من ولد؛ لم يلد ولم يولد؛ فنسبةُ الباطلِ والنقصِ إلى الله ظلمٌ عظيمٌ وافتراء؛ فمن نزّه الله عن النقصِ عظّمه، ومن نسب إليه الباطلَ ظلم؛ فاجعل تنزيهَ الله عن النقصِ والحذرَ من نسبةِ الباطلِ إليه دأبك."}},{"n":22,"reflection":{"text":"«تلك إذا قسمة ضيزى»: تلك القسمةُ (الذكورُ لكم والإناثُ لله) قسمةٌ جائرةٌ ظالمة؛ ففي هذا بيانُ ظلمِ قسمتهم؛ فاعلم أنّ ما نسبوه إلى الله ظلمٌ وجور، فنزّه الله عن كلِّ نقصٍ وجور، فالله منزّهٌ عمّا يصفون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن الجور، وإدراكُ ظلمِ ما نسبوه إليه."},"action":{"text":"تأمّل ظلمَ قسمتهم: تلك القسمةُ التي قسموها، حيث جعلوا لأنفسهم الذكورَ التي يحبّون، ولله الإناثَ التي يكرهون، قسمةٌ ضيزى، أي جائرةٌ ظالمةٌ منحرفةٌ عن العدل «تلك إذا قسمة ضيزى»؛ ففي هذا بيانُ أنّ قسمتهم ظالمةٌ جائرة؛ فحتى على زعمهم الباطل، قسمتهم ظالمة؛ فاعلم أنت أنّ ما نسبوه إلى الله من الولدِ والبناتِ ظلمٌ وجورٌ وافتراء؛ فنزّه الله عن كلِّ نقصٍ وجورٍ وباطل؛ سبحانه وتعالى عمّا يقولون علوًّا كبيرًا؛ سبحان ربّك ربِّ العزّةِ عمّا يصفون؛ فالله منزّهٌ عمّا يصفه به الجاهلون؛ ما اتّخذ الله من ولدٍ وما كان معه من إله؛ فمن نزّه الله عن الجورِ والنقصِ عظّمه، ومن نسب إليه ذلك ظلم؛ فاجعل تنزيهَ الله عن الجورِ والنقصِ دأبك."}},{"n":23,"reflection":{"text":"«إن هي إلا أسماء سميتموها أنتم وآباؤكم ما أنزل الله بها من سلطان إن يتبعون إلا الظن وما تهوى الأنفس ولقد جاءهم من ربهم الهدى»: ما هذه الأصنامُ إلا أسماءٌ سمّيتموها أنتم وآباؤكم بلا حجّة، ما أنزل الله بها من برهان؛ إن يتّبعون إلا الظنَّ وهوى الأنفس، ولقد جاءهم الهدى؛ ففي هذا إبطالُ الأصنامِ وبيانُ أنّ عبادتها ظنٌّ وهوى؛ فاحذر اتّباعَ الظنِّ والهوى في الدين، فاتّبع الهدى والدليل، فالدينُ يُبنى على الوحيِ لا على الظنِّ والهوى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الهدى والدليلِ في الدين، وتركُ الظنِّ والهوى."},"action":{"text":"تأمّل إبطالَ الأصنام: ما هذه الأصنامُ (اللاتُ والعزّى ومناة) إلا أسماءٌ ليس تحتها مسمّياتٌ تستحقّ العبادة، سمّيتموها آلهةً أنتم وآباؤكم بأهوائكم، ما أنزل الله بها من سلطانٍ وحجّةٍ وبرهان؛ إن يتّبع المشركون في عبادتها إلا الظنَّ الباطلَ وما تهوى أنفسهم؛ ولقد جاءهم من ربّهم الهدى على لسانِ الرسول، فأعرضوا عنه واتّبعوا الظنَّ والهوى «إن هي إلا أسماء سميتموها... ولقد جاءهم من ربهم الهدى»؛ ففي هذا إبطالٌ لعبادةِ الأصنام، وبيانُ أنها أسماءٌ بلا حقيقة، وأنّ عبادتها مبنيّةٌ على الظنِّ والهوى لا على الدليل؛ فاحذر أنت اتّباعَ الظنِّ والهوى في الدينِ والعبادة؛ فالدينُ يُبنى على الوحيِ والدليلِ لا على الظنِّ والتقليدِ الأعمى والهوى؛ إن يتّبعون إلا الظنَّ وإنّ الظنَّ لا يُغني من الحقِّ شيئًا؛ ومن أضلُّ ممّن اتّبع هواه بغيرِ هدًى من الله؛ فاتّبع الهدى والدليلَ الذي جاء من الله؛ فمن اتّبع الهدى اهتدى، ومن اتّبع الظنَّ والهوى ضلّ؛ فاجعل اتّباعَ الهدى والدليلِ وتركَ الظنِّ والهوى دأبك."}},{"n":24,"reflection":{"text":"«أم للإنسان ما تمنى»: أللإنسانِ كلُّ ما يتمنّاه ويشتهيه (من شفاعةِ الأصنامِ أو غيرها)؟ ففي هذا نفيُ أن ينال الإنسانُ كلَّ ما تمنّى بلا سبب؛ فاعلم أنّ الأمانيَّ لا تنفع، فاعمل ولا تتمنّ، فالنجاةُ بالعملِ لا بالتمنّي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لا التمنّي، وإدراكُ أنّ الأمانيَّ لا تنفع."},"action":{"text":"تأمّل نفيَ نيلِ كلِّ الأماني: أم للإنسانِ كلُّ ما يتمنّاه ويشتهيه من شفاعةِ الأصنامِ له، أو نيلِ ما يريد بمجرّدِ التمنّي؟ ليس الأمرُ كذلك؛ فليس له كلُّ ما تمنّى «أم للإنسان ما تمنى»؛ ففي هذا نفيٌ أن ينال الإنسانُ كلَّ ما يتمنّاه بمجرّدِ التمنّي، أو أن تنفعه شفاعةُ الأصنام؛ فالأمانيُّ الباطلةُ لا تنفع؛ فاعلم أنت أنّ الأمانيَّ المجرّدةَ عن العملِ لا تنفع ولا تُنيل المطلوب؛ ليس بأمانيّكم ولا أمانيِّ أهلِ الكتاب، من يعمل سوءًا يُجزَ به؛ فاعمل أنت ولا تتّكل على الأماني؛ فالنجاةُ والفوزُ بالعملِ الصالحِ لا بالتمنّي؛ وأن ليس للإنسانِ إلا ما سعى؛ فمن عمل نال، ومن اكتفى بالتمنّي خاب؛ فاجعل العملَ لا التمنّي دأبك."}},{"n":25,"reflection":{"text":"«فلله الآخرة والأولى»: فلله وحده أمرُ الآخرةِ والدنيا، يعطي من يشاء ويمنع؛ ففي هذا تقريرُ أنّ الأمرَ كلَّه لله؛ فاعلم أنّ الدنيا والآخرةَ بيدِ الله، فاطلب منه وحده، فمن بيده الدارانِ يُطلَب منه كلُّ خير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الخيرِ من الله وحده، وإدراكُ أنّ الدارين بيده."},"action":{"text":"تأمّل أنّ الأمرَ كلَّه لله: فلله وحده أمرُ الآخرةِ والأولى (الدنيا)، وملكهما وتدبيرهما؛ يعطي من يشاء ويمنع من يشاء بحكمته؛ فليس الأمرُ بالأمانيِّ ولا بشفاعةِ الأصنام، بل بيدِ الله «فلله الآخرة والأولى»؛ ففي هذا تقريرُ أنّ أمرَ الدنيا والآخرةِ كلَّه لله وحده؛ فهو المتصرّفُ فيهما، المالكُ لهما؛ فاعلم أنت أنّ الدنيا والآخرةَ بيدِ الله وحده، يعطي ويمنع بحكمته؛ ولله ملكُ السماواتِ والأرض؛ قل اللهم مالكَ الملكِ تؤتي الملكَ من تشاء؛ وله ما في السماواتِ وما في الأرض؛ فاطلب أنت الخيرَ من الله وحده في الدنيا والآخرة؛ فمن بيده الدارانِ يُطلَب منه كلُّ خير؛ ربّنا آتنا في الدنيا حسنةً وفي الآخرةِ حسنة؛ فمن طلب من الله وحده كُفِي، ومن طلب من غيره خاب؛ فاجعل طلبَ الخيرِ من الله وحده دأبك."}}]},{"title":"الشفاعةُ بإذنِ الله، والإعراضُ عن المؤثِرِ للدنيا، وعدلُ الجزاء","range":[26,32],"theme":"أنّ شفاعةَ الملائكةِ لا تُغني إلا بإذنِ الله ورضاه، وأنّ منكري الآخرةِ يسمّون الملائكةَ إناثًا اتّباعًا للظنّ، والأمرُ بالإعراضِ عمّن تولّى عن الذكرِ ولم يرد إلا الدنيا فذلك مبلغهم من العلم، وأنّ لله ما في السماواتِ والأرضِ ليجزيَ المسيءَ والمحسن، وصفةِ المحسنين المجتنبين للكبائرِ وسعةِ المغفرةِ والنهيِ عن تزكيةِ النفس","verses":[{"n":26,"reflection":{"text":"«وكم من ملك في السماوات لا تغني شفاعتهم شيئا إلا من بعد أن يأذن الله لمن يشاء ويرضى»، وكم من مَلَكٍ في السماواتِ لا تنفع شفاعتهم شيئًا إلا بعد إذنِ الله لمن يشاء ويرضى؛ ففي هذا بيانُ أنّ الشفاعةَ لا تكون إلا بإذنِ الله ورضاه؛ فاعلم أنّ الشفاعةَ ملكُ الله، فلا ترجُ شفاعةً بلا إذنِ الله، فاطلب رضا الله لتنال شفاعةَ من أذن له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الشفاعةَ بإذنِ الله ورضاه، وطلبُ رضاه."},"action":{"text":"تأمّل أنّ الشفاعةَ بإذنِ الله: وكم من مَلَكٍ عظيمٍ في السماواتِ، مع علوِّ منزلتهم وقربهم، لا تنفع شفاعتهم عند الله شيئًا، ولا تُقبَل، إلا من بعد أن يأذن الله لهم بالشفاعةِ لمن يشاء ويرضى عنه من الموحّدين «وكم من ملك في السماوات لا تغني شفاعتهم شيئا إلا من بعد أن يأذن الله لمن يشاء ويرضى»؛ ففي هذا بيانُ أنّ شفاعةَ الملائكةِ، فضلًا عن الأصنام، لا تنفع إلا بإذنِ الله ورضاه؛ فالشفاعةُ ملكُ الله وحده؛ فكيف تنفع الأصنامُ التي لا تسمع ولا تعقل؟ فاعلم أنت أنّ الشفاعةَ لا تكون إلا بإذنِ الله ورضاه عن الشافعِ والمشفوعِ له؛ من ذا الذي يشفع عنده إلا بإذنه؛ ولا يشفعون إلا لمن ارتضى؛ ولا تنفع الشفاعةُ عنده إلا لمن أذن له؛ فلا ترجُ شفاعةً بلا إذنِ الله؛ فاطلب رضا الله بالتوحيدِ والطاعةِ لتنال شفاعةَ من أذن له؛ فمن رضي الله عنه نالته الشفاعة، ومن سخط عليه لم تنفعه؛ فاجعل طلبَ رضا الله بالتوحيدِ والطاعةِ دأبك."}},{"n":27,"reflection":{"text":"«إن الذين لا يؤمنون بالآخرة ليسمون الملائكة تسمية الأنثى»: إنّ الذين لا يؤمنون بالآخرةِ يسمّون الملائكةَ إناثًا (بناتِ الله)؛ ففي هذا بيانُ أنّ عدمَ الإيمانِ بالآخرةِ يجرّ إلى الباطل؛ فاحذر عدمَ الإيمانِ بالآخرةِ الذي يجرّ إلى الافتراءِ على الله، فأيقن بالآخرةِ ونزّه الله، فالإيمانُ بالآخرةِ يعصم من الباطل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالآخرة، وتنزيهُ الله، والحذرُ من الافتراء."},"action":{"text":"تأمّل أنّ عدمَ الإيمانِ يجرّ للباطل: إنّ الذين لا يؤمنون بالآخرةِ والبعثِ والجزاء، ليسمّون الملائكةَ تسميةَ الأنثى، فيقولون: الملائكةُ بناتُ الله؛ فجمعوا بين إنكارِ الآخرةِ والافتراءِ على الله «إن الذين لا يؤمنون بالآخرة ليسمون الملائكة تسمية الأنثى»؛ ففي هذا بيانُ أنّ عدمَ الإيمانِ بالآخرةِ جرّهم إلى الافتراءِ على الله بنسبةِ البناتِ إليه؛ فلمّا لم يؤمنوا بالآخرةِ جرؤوا على الباطل؛ فاحذر أنت عدمَ الإيمانِ بالآخرةِ الذي يجرّ إلى الافتراءِ على الله والجرأةِ على الباطل؛ فأيقن بالآخرةِ والبعثِ والجزاء؛ ونزّه الله عن الولدِ والبناتِ وكلِّ نقص؛ وجعلوا الملائكةَ الذين هم عبادُ الرحمنِ إناثًا، أشهدوا خلقهم؟ ستُكتَب شهادتهم ويُسألون؛ فالإيمانُ بالآخرةِ يعصم من الباطلِ والافتراء؛ فمن آمن بالآخرةِ اتّقى الافتراء، ومن أنكرها جرؤ على الباطل؛ فاجعل اليقينَ بالآخرةِ وتنزيهَ الله دأبك."}},{"n":28,"reflection":{"text":"«وما لهم به من علم إن يتبعون إلا الظن وإن الظن لا يغني من الحق شيئا»، وما لهم بهذا القولِ (أنّ الملائكةَ بناتُ الله) من علم، ما يتّبعون إلا الظنَّ، والظنُّ لا يُغني من الحقِّ شيئًا؛ ففي هذا ذمُّ اتّباعِ الظنِّ في الدين؛ فاحذر القولَ في الدينِ بالظنِّ بلا علم، فاطلب العلمَ واليقين، فالظنُّ لا يُغني عن الحق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العلمِ واليقين، وتركُ اتّباعِ الظنِّ في الدين."},"action":{"text":"تأمّل ذمَّ اتّباعِ الظن: وما للمشركين بهذا القولِ، إنّ الملائكةَ بناتُ الله، من علمٍ صحيحٍ يستندون إليه؛ ما يتّبعون في ذلك إلا الظنَّ والوهمَ والتخمين؛ وإنّ الظنَّ لا يُغني من الحقِّ شيئًا، ولا يقوم مقامَ العلمِ واليقين «وما لهم به من علم إن يتبعون إلا الظن وإن الظن لا يغني من الحق شيئا»؛ ففي هذا ذمُّ اتّباعِ الظنِّ في أمورِ الدينِ والاعتقاد، وبيانُ أنّ الظنَّ لا يُغني عن العلمِ والحق؛ فبنوا اعتقادهم على الظنِّ لا العلم؛ فاحذر أنت القولَ في الدينِ والاعتقادِ بالظنِّ والوهمِ بلا علمٍ ولا يقين؛ ولا تقف ما ليس لك به علم، إنّ السمعَ والبصرَ والفؤادَ كلُّ أولئك كان عنه مسؤولًا؛ إن يتّبعون إلا الظنَّ وما تهوى الأنفس؛ فاطلب العلمَ واليقينَ في أمورِ دينك واعتقادك؛ فالظنُّ لا يُغني من الحقِّ شيئًا ولا يقوم مقامَ اليقين؛ فمن بنى دينه على العلمِ واليقينِ اهتدى، ومن بناه على الظنِّ ضلّ؛ فاجعل طلبَ العلمِ واليقينِ وتركَ اتّباعِ الظنِّ دأبك."}},{"n":29,"reflection":{"text":"«فأعرض عن من تولى عن ذكرنا ولم يرد إلا الحياة الدنيا»: فأعرض، يا محمدُ، عمّن أعرض عن القرآنِ وذكرِنا ولم يرد إلا الحياةَ الدنيا؛ ففي هذا بيانُ حالِ من آثر الدنيا؛ فاحذر أن تكون ممّن يُعرِض عن الذكرِ ويقصر همّه على الدنيا، فاجعل همّك الآخرةَ والذكر، فمن أعرض عن الذكرِ وآثر الدنيا خسر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على الذكرِ وطلبُ الآخرة، والحذرُ من إيثارِ الدنيا."},"action":{"text":"تأمّل حالَ من آثر الدنيا: فأعرض، يا محمدُ، عمّن تولّى وأعرض عن ذكرِنا (القرآنِ والإيمانِ والتوحيد)، ولم يرد ولم يطلب إلا الحياةَ الدنيا وزينتها وشهواتها، فجعلها غايةَ همّه وعلمه «فأعرض عن من تولى عن ذكرنا ولم يرد إلا الحياة الدنيا»؛ ففي هذا بيانُ حالِ المعرضِ عن الذكرِ المؤثِرِ للدنيا، والأمرِ بالإعراضِ عنه؛ فمن أعرض عن ذكرِ الله وقصر همّه على الدنيا فهو خاسر؛ فاحذر أنت أن تكون ممّن يُعرِض عن ذكرِ الله والقرآن، ويقصر همّه ومطلبه على الدنيا وحدها؛ ومن أعرض عن ذكري فإنّ له معيشةً ضنكًا؛ يعلمون ظاهرًا من الحياةِ الدنيا وهم عن الآخرةِ هم غافلون؛ فاجعل همّك الآخرةَ والإقبالَ على ذكرِ الله والقرآن؛ ولا تجعل الدنيا أكبرَ همّك؛ فمن أقبل على الذكرِ وطلب الآخرةَ سعد، ومن أعرض عن الذكرِ وآثر الدنيا خسر؛ فاجعل الإقبالَ على الذكرِ وطلبَ الآخرةِ دأبك."}},{"n":30,"reflection":{"text":"«ذلك مبلغهم من العلم إن ربك هو أعلم بمن ضل عن سبيله وهو أعلم بمن اهتدى»: ذلك (إيثارُ الدنيا) منتهى علمهم وهمّهم، إنّ ربّك أعلمُ بمن ضلَّ عن سبيله ومن اهتدى؛ ففي هذا بيانُ أنّ إيثارَ الدنيا غايةُ علمِ الغافلين؛ فارفع همّتك فوق الدنيا إلى العلمِ النافعِ والآخرة، فمن كان علمه الدنيا فقط فهو قاصرُ الهمّة، والله أعلمُ بالمهتدي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"رفعُ الهمّةِ للعلمِ النافعِ والآخرة، وتركُ قصرِ العلمِ على الدنيا."},"action":{"text":"تأمّل أنّ إيثارَ الدنيا غايةُ علمِ الغافلين: ذلك الإقبالُ على الدنيا والإعراضُ عن الآخرةِ هو مبلغُ هؤلاء ومنتهى علمهم وهمّهم، فلا يعلمون إلا الدنيا؛ إنّ ربّك هو أعلمُ بمن ضلَّ عن سبيله فآثر الدنيا، وهو أعلمُ بمن اهتدى فآثر الآخرة؛ فهو يجازي كلًّا بحاله «ذلك مبلغهم من العلم إن ربك هو أعلم بمن ضل عن سبيله وهو أعلم بمن اهتدى»؛ ففي هذا بيانُ أنّ إيثارَ الدنيا غايةُ علمِ الغافلين وهمّتهم القاصرة، وأنّ الله أعلمُ بالضالِّ والمهتدي؛ فمن كان علمه وهمّه الدنيا فقط فهو قاصرُ الهمّة؛ فارفع أنت همّتك فوق الدنيا إلى العلمِ النافعِ والعملِ للآخرة؛ فلا تجعل الدنيا منتهى علمك وهمّك؛ يعلمون ظاهرًا من الحياةِ الدنيا؛ وفوق كلِّ ذي علمٍ عليم؛ واعلم أنّ الله أعلمُ بالمهتدي والضالّ، فاحرص أن تكون من المهتدين؛ فمن رفع همّته للآخرةِ والعلمِ النافعِ اهتدى، ومن قصرها على الدنيا ضلّ؛ فاجعل رفعَ الهمّةِ للعلمِ النافعِ والآخرةِ دأبك."}},{"n":31,"reflection":{"text":"«ولله ما في السماوات وما في الأرض ليجزي الذين أساءوا بما عملوا ويجزي الذين أحسنوا بالحسنى»، ولله ما في السماواتِ والأرض، ليجزيَ المسيئين بأعمالهم والمحسنين بالجنّة؛ ففي هذا بيانُ عدلِ الجزاءِ ومُلكِ الله؛ فأحسن في عملك لتُجزى بالحسنى، فالجزاءُ بالعمل، فاعمل إحسانًا لتنال الجزاءَ الأحسن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ في العملِ لنيلِ الجزاءِ الأحسن، وإدراكُ عدلِ الله."},"action":{"text":"تأمّل عدلَ الجزاءِ ومُلكَ الله: ولله وحده ما في السماواتِ وما في الأرضِ خلقًا ومُلكًا وتدبيرًا؛ خلقهم وملكهم ليجزيَ الذين أساءوا وعملوا السيّئاتِ بما عملوا من الشرِّ عدلًا؛ ويجزيَ الذين أحسنوا في إيمانهم وأعمالهم بالحسنى، وهي الجنّةُ، فضلًا «ولله ما في السماوات وما في الأرض ليجزي الذين أساءوا بما عملوا ويجزي الذين أحسنوا بالحسنى»؛ ففي هذا بيانُ أنّ المُلكَ كلَّه لله، وأنّ من حكمةِ الخلقِ الجزاءَ العادلَ: للمسيءِ بإساءته، وللمحسنِ بالحسنى؛ فالجزاءُ بالعمل؛ فأحسن أنت في عملك، في عبادةِ الله وفي معاملةِ خلقه، لتُجزى بالحسنى (الجنّة)؛ هل جزاءُ الإحسانِ إلا الإحسان؛ للذين أحسنوا الحسنى وزيادة؛ ومن أساء فعليها؛ فالجزاءُ بقدرِ العملِ عدلًا وفضلًا؛ فمن أحسن جُوزي بالحسنى، ومن أساء جُوزي بإساءته؛ فاجعل الإحسانَ في العملِ سبيلَ نيلِ الجزاءِ الأحسن."}},{"n":32,"reflection":{"text":"«الذين يجتنبون كبائر الإثم والفواحش إلا اللمم إن ربك واسع المغفرة... فلا تزكوا أنفسكم هو أعلم بمن اتقى»: المحسنون الذين يجتنبون كبائرَ الإثمِ والفواحشَ إلا صغائرَ اللمم، إنّ ربّك واسعُ المغفرة، هو أعلمُ بكم منذ أنشأكم، فلا تزكّوا أنفسكم، هو أعلمُ بمن اتّقى؛ ففي هذا بيانُ صفةِ المحسنين وسعةِ المغفرةِ والنهيُ عن تزكيةِ النفس؛ فاجتنب الكبائرَ والفواحش، وارجُ مغفرةَ الله الواسعة، ولا تزكِّ نفسك، فالتقوى في القلبِ يعلمها الله، والعبرةُ بحقيقةِ التقوى لا بدعواها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الكبائرِ ورجاءُ المغفرة، وتركُ تزكيةِ النفس."},"action":{"text":"تأمّل صفةَ المحسنين والنهيَ عن التزكية: المحسنون هم الذين يجتنبون كبائرَ الإثمِ (كالشركِ والقتلِ والزنا) والفواحشَ العظيمة، إلا اللممَ، وهي صغائرُ الذنوبِ التي تُكفَّر باجتنابِ الكبائرِ والحسنات؛ إنّ ربّك واسعُ المغفرةِ لمن اجتنب الكبائرَ وتاب؛ هو أعلمُ بكم إذ أنشأكم من الأرضِ (خلقِ آدم) وإذ أنتم أجنّةٌ في بطونِ أمّهاتكم؛ فلا تزكّوا أنفسكم وتمدحوها بالطهارةِ والتقوى؛ هو أعلمُ بمن اتّقى حقيقةً «الذين يجتنبون كبائر الإثم والفواحش إلا اللمم... فلا تزكوا أنفسكم هو أعلم بمن اتقى»؛ ففي هذا بيانُ صفةِ المحسنين (اجتنابُ الكبائرِ والفواحش)، وسعةِ مغفرةِ الله، والنهيِ عن تزكيةِ النفسِ والإعجابِ بها؛ فاجتنب أنت كبائرَ الإثمِ والفواحش؛ إن تجتنبوا كبائرَ ما تُنهَون عنه نكفّر عنكم سيّئاتكم؛ وارجُ مغفرةَ الله الواسعةَ لمن اجتنب الكبائرَ وتاب؛ ولا تزكِّ نفسك ولا تمدحها ولا تُعجَب بها؛ فالله أعلمُ بحقيقةِ تقواك؛ فالتقوى في القلبِ يعلمها الله لا الدعوى؛ إنّ أكرمكم عند الله أتقاكم؛ فمن اجتنب الكبائرَ ولم يزكِّ نفسه فاز، ومن أصرّ عليها أو أُعجِب بنفسه خسر؛ فاجعل اجتنابَ الكبائرِ ورجاءَ المغفرةِ وتركَ تزكيةِ النفسِ دأبك."},"qadiyya":{"title":"قضيّةُ تزكية النفس: آيةٌ تمدح المحسنين ثمّ تنهاهم أن يُزكّوا أنفسهم","question":"في سورة النجم وصفٌ لأهل الإحسان: «**الذين يجتنبون كبائرَ الإثم والفواحش إلّا اللمم**». وهذا وصفٌ يطمع فيه كلُّ مسلم، **وأكثرُ الناس يظنّ نفسَه داخلًا فيه**؛ فإنّه لا يقتل ولا يزني ولا يسرق.\n**ثمّ جاء في الآية نفسِها ما يقطع هذا الطمع**: «**فلا تزكّوا أنفسكم، هو أعلمُ بمن اتّقى**».\nفالسؤال: **لماذا يُذكر الوصفُ ثمّ يُنهى عن ادّعائه في نَفَسٍ واحد؟** وما «اللمم» الذي استُثني؟ **وهل هو بابٌ مفتوحٌ للتساهل أم قيدٌ مضبوط؟**","background":"ولا يُفهم هذا حتى تُعرف قسمةُ الذنوب من الصفر:\n**الكبائر**: ما رتّب الشرعُ عليه حدًّا في الدنيا أو وعيدًا خاصًّا في الآخرة، كالقتل والزنا والربا وشرب الخمر.\n**والصغائر**: ما دون ذلك.\n**واللَّمَم**: من «ألمَّ بالشيء» إذا قاربه ولم يُقم عليه. **فالوصفُ في اللفظ نفسِه يحمل معنى القلّة وعدم الإقامة.**\n**وأمرٌ رابعٌ يخصّ سياق الآية**: أنّ السورة نزلت في مكّة، وكان بعض المشركين يزكّون أنفسهم ويفخرون بأعمالهم، **فجاء النهيُ في سياق بيان من هو المحسنُ حقًّا**.","what_happened":"**أمّا «اللمم» فقد حدَّه السعديُّ حدًّا يمنع التوسّع فيه.** قال: «**وهي الذنوبُ الصغار، التي لا يُصرّ صاحبُها عليها، أو التي يُلمّ بها العبد، المرّةَ بعد المرّة، على وجه الندرة والقلّة**».\n**فتأمّل القيدين**: **ألّا يُصرّ**، و**أن تكون على وجه الندرة والقلّة**. **فالإصرارُ على الصغيرة يُخرجها من اللمم؛ ومن واظب على ذنبٍ صغيرٍ فليس ملمًّا به، بل مقيمًا عليه.**\n**ثمّ بيّن أين تقع هذه من المغفرة**: «**فإنّ هذه مع الإتيان بالواجبات وترك المحرّمات، تدخل تحت مغفرة الله التي وسعت كلَّ شيء**». **فالشرطُ مذكور: أداءُ الواجبات وتركُ المحرّمات.**\n**واستدلّ بحديث النبيّ ﷺ**: «**الصلواتُ الخمس، والجمعةُ إلى الجمعة، ورمضانُ إلى رمضان، مكفّراتٌ لما بينهنّ، ما اجتُنبت الكبائر**».\n**ثمّ وقف السعديُّ عند قوله ﴿هو أعلمُ بكم إذ أنشأكم من الأرض﴾ وقفةً لطيفة**، فجعلها **عذرًا مقدَّمًا** لا تهديدًا: «**هو تعالى أعلمُ بأحوالكم كلِّها، وما جبلكم عليه، من الضعف والخَور**»، ومن «كثرة الدواعي إلى بعض المحرّمات».\n**فالذي يعلم ضعفَك هو الذي وسّع لك المغفرة.**\n**وعظّم السعديُّ شأنَ هذه المغفرة** فقال: «**فلولا مغفرتُه لهلكت البلادُ والعباد**».\n**ثمّ جاء النهي**: ﴿فلا تزكّوا أنفسكم﴾، وعقّبه ﴿هو أعلمُ بمن اتّقى﴾.","the_verdict":"**فالحاصلُ أنّ الآية بنت شيئًا ثمّ سدّت بابَ الدخول إليه بالدعوى.**\nفهي **وصفت** المحسنين وصفًا دقيقًا فيه قيود؛ **ثمّ نهت أن يقول أحدٌ عن نفسه إنّه منهم.** **فليس النهيُ عن السعي إلى الوصف، بل عن الحكم بأنّك بلغته.**\n**والعلّةُ في ختام الآية**: ﴿هو أعلمُ بمن اتّقى﴾. **فالتقوى موضعُها القلبُ، والقلبُ لا يطّلع عليه صاحبُه اطّلاعًا تامًّا فضلًا عن غيره.** والرجلُ قد يترك الكبيرةَ عجزًا فيحسبها ورعًا، وقد يفعل الطاعةَ رياءً فيحسبها إخلاصًا.\n**⭐ وموضعُ «اللمم» من هذا دقيق**: فقد يُظنّ أنّه رخصةٌ تُطمئن المقصّر. **وليس كذلك، لموضعين في كلام السعديّ:**\nالأوّل: **قيدُ عدم الإصرار**. فمن كان له ذنبٌ صغيرٌ يواظب عليه، **فقد خرج من اللمم بالمواظبة، لا بحجم الذنب.**\nوالثاني: **أنّه معلّقٌ بشرط**: «مع الإتيان بالواجبات وترك المحرّمات». **فمن ضيّع الواجبات فليس كلامُنا فيه.**\n**فاللممُ إذًا ليس بابًا للتساهل، بل رحمةٌ بمن استقام فزلّ.**\n**وأمّا الجمعُ بين سعة المغفرة والنهي عن التزكية فهو تمامُ الأدب**: **تُوسَّع لك الرحمةُ لئلّا تيأس، ويُسدّ عليك بابُ الدعوى لئلّا تأمن.** **فالمؤمن بين الرجاء والخوف، وهذه الآيةُ تجمعهما في سطرين.**","for_you":"**فأمّا الذي تخرج به فثلاثة:**\n**الأوّل: احذر التزكية في صيغتها الخفيّة.** فليس أحدٌ يقول «أنا تقيّ»؛ **لكنّ التزكية تخرج في صورٍ أخرى**: أن تقارن نفسَك بمن هو دونك فترتاح، أو تحدّث الناسَ عن عبادتك بغير حاجة، أو تستقلّ ذنبَك لأنّك تراه صغيرًا في نفسك. **والنهيُ عن التزكية نهيٌ عن الحكم، لا عن الرجاء.**\n**والثاني، وهو محكٌّ للصغائر**: لا تسألْ: أكبيرٌ هذا أم صغير؟ **بل اسأل: هل أنا مصرٌّ عليه؟** فإنّ الصغيرةَ مع الإصرار تخرج من اللمم؛ **وقد جرت على ألسنة أهل العلم كلمةٌ معناها أنّه لا صغيرةَ مع إصرار، ولم نجدها بلفظها في كتبنا الستّة فلا ننسبها.** **فانظر في ذنبٍ تعيده كلَّ أسبوع منذ سنة: ذاك ليس لممًا، وإن كان في نفسه صغيرًا.**\n**والثالث: خذ من ﴿هو أعلمُ بكم إذ أنشأكم﴾ رجاءً لا عذرًا.** فقد جعلها السعديُّ في سياق **علم الله بضعفك**. **فالذي خلقك يعلم أنّك ستزلّ، ولم يكلّفك ألّا تزلّ، بل كلّفك ألّا تُصرّ.** **فمن سقط فليقم، ولا يجعل من علم الله بضعفه رخصةً في الإقامة على السقوط.**","grade":"ma'thur","source":"حدُّ اللمم عند السعديّ («وهي الذنوب الصغار، التي لا يصر صاحبها عليها، أو التي يلم بها العبد، المرة بعد المرة، على وجه الندرة والقلة»)، وشرطُه («فإن هذه مع الإتيان بالواجبات وترك المحرمات، تدخل تحت مغفرة الله التي وسعت كل شيء»)، وحديثُ «الصلوات الخمس، والجمعة إلى الجمعة، ورمضان إلى رمضان، مكفرات لما بينهن، ما اجتنبت الكبائر» كما أورده، وقولُه في ﴿هو أعلم بكم﴾ («هو تعالى أعلم بأحوالكم كلها، وما جبلكم عليه، من الضعف والخور»)، وقولُه «فلولا مغفرته لهلكت البلاد والعباد»: كلُّها بنصّها في تفسير السعديّ (٥٣:٣٢).","honesty":"وممّا يجب أن يُقال:\n**الحديثُ أورده السعديُّ في تفسيره ولم نرجع به إلى أصله**، فليست كتبُ السنّة في كتب هذا المشروع؛ **والعهدةُ في نسبته على من أورده.**\n**وأمّا الكلمةُ المشهورةُ في أنّه لا صغيرةَ مع إصرار، فلم نجدها بلفظها في كتبنا الستّة**، فلم ننسبها إلى أحد ولم نضعها بين قوسي النقل؛ وإنّما ذكرنا معناها لأنّه **لازمُ قيد السعديّ**، ومن شاء فليقف عند لفظ السعديِّ وحده.\n**وأمّا تفصيلُ ما هو من الكبائر وما هو من الصغائر ففيه كلامٌ طويلٌ لأهل العلم**، ومظانُّه كتبُ الأحكام، ولم نتعرّض له.\n**وأمّا قولُنا إنّ أكثر الناس يظنّ نفسَه داخلًا في الوصف فهو وصفٌ لواقعٍ نراه، لا إحصاءَ عندنا به.**"}}]},{"title":"مبادئُ صحفِ إبراهيمَ وموسى: العدلُ والسعي","range":[33,42],"theme":"التعجّبُ من المتولّي الذي أعطى قليلًا وأكدى، وسؤالُه أعنده علمُ الغيب، والتذكيرُ بما في صحفِ موسى وإبراهيمَ الذي وفّى: ألا تزر وازرةٌ وزرَ أخرى، وأن ليس للإنسانِ إلا ما سعى وأنّ سعيه سوف يُرى ثم يُجزاه الجزاءَ الأوفى، وأنّ إلى ربّك المنتهى","verses":[{"n":33,"reflection":{"text":"«أفرأيت الذي تولى»: أفرأيت الذي أعرض عن الحقِّ والطاعة؟ ففي هذا بيانُ حالِ المعرض؛ فاحذر التولّيَ والإعراضَ عن الحقّ، فأقبل على الطاعةِ ولا تُعرِض، فالإعراضُ عن الحقِّ سببُ الخسران.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقبالُ على الطاعة، والحذرُ من التولّي عن الحق."},"action":{"text":"تأمّل حالَ المعرض: أفرأيت، يا محمدُ، الذي تولّى وأعرض عن الحقِّ والطاعةِ والإيمان، بعد أن كان قريبًا منه (وقيل نزلت في رجلٍ همّ بالإسلامِ ثم أعرض حين خُوّف)؛ فبخل واستكبر «أفرأيت الذي تولى»؛ ففي هذا بيانُ حالِ المعرضِ المتولّي عن الحق، على سبيلِ التعجّبِ من حاله؛ فأعرض عن الطاعةِ والإنفاقِ خوفًا وبخلًا؛ فاحذر أنت التولّيَ والإعراضَ عن الحقِّ والطاعة؛ فأقبل على الطاعةِ والإنفاقِ ولا تُعرِض؛ فأمّا من أعطى واتّقى وصدّق بالحسنى فسنيسّره لليسرى، وأمّا من بخل واستغنى وكذّب بالحسنى فسنيسّره للعسرى؛ فالإعراضُ عن الحقِّ والطاعةِ سببُ الخسران؛ فمن أقبل على الطاعةِ سعد، ومن تولّى عنها خسر؛ فاجعل الإقبالَ على الطاعةِ والحذرَ من التولّي دأبك."}},{"n":34,"reflection":{"text":"«وأعطى قليلا وأكدى»، وأعطى قليلًا من المالِ ثم قطع العطاءَ وبخل؛ ففي هذا ذمُّ البخلِ وقطعِ العطاء؛ فاحذر البخلَ وقطعَ الإنفاق، فأنفق بسخاءٍ ودوام، فالبخلُ وقطعُ العطاءِ من صفاتِ المعرضين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنفاقُ بسخاءٍ ودوام، والحذرُ من البخلِ وقطعِ العطاء."},"action":{"text":"تأمّل ذمَّ البخل: وأعطى ذلك المتولّي قليلًا من المال، ثم أكدى، أي قطع عطاءه وأمسك وبخل، ولم يستمرّ في الإنفاق؛ فبدأ ثم قطع «وأعطى قليلا وأكدى»؛ ففي هذا ذمُّ البخلِ وقطعِ العطاءِ بعد الشروعِ فيه؛ فأعطى قليلًا ثم قطع؛ فاحذر أنت البخلَ وقطعَ الإنفاقِ والعطاء؛ فأنفق بسخاءٍ ودوامٍ في سبيلِ الله؛ ومن يبخل فإنما يبخل عن نفسه؛ ولا تجعل يدك مغلولةً إلى عنقك ولا تبسطها كلَّ البسط؛ الذين ينفقون في السرّاءِ والضرّاء؛ فالبخلُ وقطعُ العطاءِ من صفاتِ المعرضين المتولّين؛ وأحضرتِ الأنفسُ الشحّ؛ فمن أنفق بسخاءٍ نال الأجرَ والبركة، ومن بخل وقطع حُرِم؛ فاجعل الإنفاقَ بسخاءٍ ودوامٍ وتركَ البخلِ دأبك."}},{"n":35,"reflection":{"text":"«أعنده علم الغيب فهو يرى»: أعند هذا المتولّي علمُ الغيبِ فهو يرى أنه سيُحمَل عنه وزره، أو أنّ الإنفاقَ يُفقِره؟ ففي هذا إنكارٌ على من يبني عمله على ظنٍّ بلا علم؛ فاعلم أنّ الغيبَ لله، فلا تبنِ عملك على أوهام، بل على العلمِ واليقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"بناءُ العملِ على العلمِ واليقين، وردُّ الغيبِ لله."},"action":{"text":"تأمّل الإنكارَ على المتولّي: أعند هذا الذي تولّى وبخل علمُ الغيبِ فهو يرى ويعلم أنّ ما عنده من الحقِّ سيحمله عنه غيره، أو أنّ الإنفاقَ يُفقِره، أو أنه ناجٍ بلا عمل؟ لا علمَ عنده بذلك «أعنده علم الغيب فهو يرى»؛ ففي هذا إنكارٌ على المتولّي البخيلِ الذي بنى إعراضه وبخله على ظنونٍ وأوهامٍ بلا علم؛ فبخل ظنًّا أنّ الإنفاقَ يُفقِره، أو تولّى ظنًّا أنّ غيره يحمل عنه؛ فاعلم أنت أنّ الغيبَ لله وحده، لا يعلمه أحد؛ فلا تبنِ عملك أو تركك للعملِ على أوهامٍ وظنون؛ بل ابنِه على العلمِ واليقينِ والدليل؛ ولا تقف ما ليس لك به علم؛ فمن بنى عمله على العلمِ واليقينِ اهتدى، ومن بناه على الظنِّ والوهمِ ضلّ؛ فاجعل بناءَ العملِ على العلمِ واليقينِ وردَّ الغيبِ لله دأبك."}},{"n":36,"reflection":{"text":"«أم لم ينبأ بما في صحف موسى»: ألم يُخبَر هذا المتولّي بما في صحفِ موسى (التوراة) من الحقائق؟ ففي هذا تذكيرٌ بما في الكتبِ السابقةِ من الحقائق؛ فتعلّم الحقائقَ الثابتةَ في الوحي، فما في الكتبِ من الحقِّ حجّةٌ عليك، فاعمل بها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعلّمُ الحقائقِ الثابتةِ في الوحيِ والعملُ بها."},"action":{"text":"تأمّل التذكيرَ بصحفِ موسى: أم لم يُنبَّأ ويُخبَر هذا المتولّي البخيلُ بما في صحفِ موسى، أي التوراةِ أو الصحفِ المنزَّلةِ عليه، من الحقائقِ والحكمِ العظيمة؟ فلو علمها لعمل بها «أم لم ينبأ بما في صحف موسى»؛ ففي هذا تذكيرٌ بما في الكتبِ السابقة (صحفِ موسى) من الحقائقِ الثابتة، توبيخًا للمعرض؛ فهذه الحقائقُ ثابتةٌ في الوحيِ كلِّه؛ فتعلّم أنت الحقائقَ الثابتةَ في الوحيِ (القرآنِ والكتبِ السابقة)؛ فما في الكتبِ من الحقِّ حجّةٌ عليك وهدايةٌ لك؛ إنّ هذا لفي الصحفِ الأولى، صحفِ إبراهيمَ وموسى؛ فاعمل بالحقائقِ الثابتةِ في الوحي؛ فمن تعلّم الحقائقَ وعمل بها اهتدى، ومن أعرض عنها ضلّ؛ فاجعل تعلّمَ الحقائقِ الثابتةِ في الوحيِ والعملَ بها دأبك."}},{"n":37,"reflection":{"text":"«وإبراهيم الذي وفى»، وصحفِ إبراهيمَ الذي وفّى بما أُمِر به وبلّغه وقام بحقِّ العبودية؛ ففي هذا الثناءُ على إبراهيمَ بالوفاء؛ فاقتدِ بإبراهيمَ في الوفاءِ بالعهدِ والقيامِ بحقِّ الله، فالوفاءُ بالعهدِ من صفاتِ الأنبياء، فاجعله دأبك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بإبراهيمَ في الوفاءِ بالعهدِ والقيامِ بحقِّ الله."},"action":{"text":"تأمّل الثناءَ على إبراهيمَ بالوفاء: وصحفِ إبراهيمَ الخليلِ الذي وفّى، أي وفّى بجميعِ ما أُمِر به، وقام بحقِّ العبوديةِ والدعوةِ والبلاغ، وبلّغ رسالاتِ ربّه، وصبر على الابتلاءِ (كذبحِ ابنه وإلقائه في النار)؛ فوفّى وفاءً كاملًا «وإبراهيم الذي وفى»؛ ففي هذا ثناءٌ على إبراهيمَ عليه السلام بوفائه التامِّ بما أُمِر به؛ فوفّى بعهدِ الله وأمره وبلاغه؛ فاقتدِ أنت بإبراهيمَ في الوفاءِ بالعهدِ والقيامِ بحقِّ الله وأمره؛ وأوفوا بعهدِ الله إذا عاهدتم؛ والموفون بعهدهم إذا عاهدوا؛ يوفون بالنذر؛ فالوفاءُ بالعهدِ والقيامُ بحقِّ الله من صفاتِ الأنبياءِ والصالحين؛ فمن وفّى بعهدِ الله وأمره أكرمه الله، ومن غدر ونقض خسر؛ فاجعل الاقتداءَ بإبراهيمَ في الوفاءِ بالعهدِ والقيامِ بحقِّ الله دأبك."}},{"n":38,"reflection":{"text":"«ألا تزر وازرة وزر أخرى»: من الحقائقِ في الصحف: ألا تحمل نفسٌ آثمةٌ ذنبَ نفسٍ أخرى؛ ففي هذا تقريرُ عدلِ الله في المسؤوليةِ الفردية؛ فاعلم أنّ كلَّ نفسٍ تحمل وزرها وحده، فلا تتّكل على أحدٍ يحمل عنك، فاعمل لنفسك، فالمسؤوليةُ فردية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنفس، وإدراكُ المسؤوليةِ الفرديةِ وعدلِ الله."},"action":{"text":"تأمّل عدلَ المسؤوليةِ الفردية: من الحقائقِ العظيمةِ في صحفِ موسى وإبراهيم: أنه لا تزر وازرةٌ وزرَ أخرى، أي لا تحمل نفسٌ مذنبةٌ ذنبَ نفسٍ أخرى، ولا يؤخَذ أحدٌ بجريرةِ غيره؛ بل كلُّ نفسٍ تحمل وزرها «ألا تزر وازرة وزر أخرى»؛ ففي هذا تقريرُ عدلِ الله في المسؤوليةِ الفردية، وأنّ كلَّ نفسٍ محاسبةٌ بعملها وحدها؛ فلا يحمل أحدٌ ذنبَ أحد؛ فرَدَّ على المتولّي الذي ظنّ أنّ غيره يحمل عنه؛ فاعلم أنت أنّ كلَّ نفسٍ تحمل وزرها ومسؤوليّتها وحدها؛ ولا تزر وازرةٌ وزرَ أخرى؛ وكلُّ إنسانٍ ألزمناه طائره في عنقه؛ فلا تتّكل على أحدٍ يحمل عنك ذنبك؛ ولا يحمل أحدٌ عنك يومَ القيامة؛ فاعمل لنفسك عملًا صالحًا ينفعك؛ فمن عمل لنفسه نجا، ومن اتّكل على غيره خاب؛ فاجعل العملَ للنفسِ وإدراكَ المسؤوليةِ الفرديةِ دأبك."}},{"n":39,"reflection":{"text":"«وأن ليس للإنسان إلا ما سعى»، وأنه ليس للإنسانِ من الجزاءِ إلا ما سعى وعمل؛ ففي هذا تقريرُ أنّ الجزاءَ بالسعيِ والعمل؛ فاسعَ واعمل، فلا ينفعك إلا سعيك، فمن أراد الفوزَ فليسعَ له، فالجزاءُ ثمرةُ السعي.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"السعيُ والعملُ للفوز، وإدراكُ أنّ الجزاءَ بالسعي."},"action":{"text":"تأمّل أنّ الجزاءَ بالسعي: ومن الحقائقِ في الصحف: أنه ليس للإنسانِ من الجزاءِ والثوابِ إلا ما سعى وعمله بنفسه من خير؛ فلا ينفعه سعيُ غيره ولا يناله إلا بسعيه «وأن ليس للإنسان إلا ما سعى»؛ ففي هذا تقريرُ أنّ جزاءَ الإنسانِ مبنيٌّ على سعيه وعمله، وأنه لا ينال إلا ما سعى له؛ فالفوزُ بالسعيِ والعمل، لا بالأمانيِّ ولا بسعيِ الغير؛ فاسعَ أنت واعمل للفوزِ والنجاة؛ فلا ينفعك يومَ القيامةِ إلا سعيك وعملك الصالح؛ فمن كان يرجو لقاءَ ربّه فليعمل عملًا صالحًا؛ ومن أراد الآخرةَ وسعى لها سعيها وهو مؤمنٌ فأولئك كان سعيهم مشكورًا؛ ليس بأمانيّكم؛ فمن أراد الفوزَ فليسعَ له بالعمل؛ فالجزاءُ ثمرةُ السعيِ والعمل؛ فمن سعى وعمل نال، ومن كسل وتمنّى خاب؛ فاجعل السعيَ والعملَ للفوزِ دأبك."}},{"n":40,"reflection":{"text":"«وأن سعيه سوف يرى»، وأنّ سعيَه وعمله سوف يُرى ويُعرَض يومَ القيامة؛ ففي هذا بيانُ أنّ الأعمالَ ستُعرَض؛ فأخلص عملك وأحسنه، فسيُعرَض عليك يومَ القيامة، فما تعمله محفوظٌ سيُرى، فاحرص أن تراه حسنًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ العملِ وإحسانُه، وإدراكُ أنه سيُعرَض ويُرى."},"action":{"text":"تأمّل أنّ السعيَ سيُرى: وأنّ سعيَ الإنسانِ وعمله، خيرَه وشرَّه، سوف يُرى ويُعرَض عليه يومَ القيامة، ويُشاهِده في صحيفته، ثم يُجازى عليه «وأن سعيه سوف يرى»؛ ففي هذا بيانُ أنّ أعمالَ الإنسانِ ستُعرَض عليه وتُرى يومَ القيامة؛ فيرى عمله محفوظًا مسطورًا؛ فأخلص أنت عملك وأحسنه؛ فسيُعرَض عليك ويُرى يومَ القيامة؛ يومئذٍ يصدر الناسُ أشتاتًا ليُرَوا أعمالهم، فمن يعمل مثقالَ ذرّةٍ خيرًا يره ومن يعمل مثقالَ ذرّةٍ شرًّا يره؛ ووجدوا ما عملوا حاضرًا؛ ونُخرِج له يومَ القيامةِ كتابًا يلقاه منشورًا؛ فما تعمله محفوظٌ سيُرى ويُعرَض؛ فاحرص أن تراه حسنًا يسرّك؛ فمن أحسن عمله سُرّ برؤيته، ومن أساءه ساءه؛ فاجعل إخلاصَ العملِ وإحسانَه دأبك."}},{"n":41,"reflection":{"text":"«ثم يجزاه الجزاء الأوفى»: ثم يُجزى الإنسانُ سعيَه الجزاءَ الأوفى الأكمل؛ ففي هذا بيانُ كمالِ الجزاء؛ فاعمل صالحًا واثقًا بأنّ الله يوفّيك جزاءه كاملًا، فالجزاءُ أوفى وأكمل، فاحرص على العملِ الصالح.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ ثقةً بالجزاءِ الأوفى الكامل."},"action":{"text":"تأمّل كمالَ الجزاء: ثم يُجزى الإنسانُ سعيَه وعمله الجزاءَ الأوفى، أي الأكملَ الأتمَّ الوافي: إن كان خيرًا فخير، وإن كان شرًّا فشر، بلا نقص «ثم يجزاه الجزاء الأوفى»؛ ففي هذا بيانُ أنّ الله يجزي الإنسانَ على سعيه جزاءً وافيًا كاملًا لا نقصَ فيه؛ فيوفّيه جزاءه؛ فاعمل أنت صالحًا واثقًا بأنّ الله يوفّيك جزاءه كاملًا مضاعفًا؛ ووُفّيت كلُّ نفسٍ ما عملت؛ وإنما توفّون أجوركم يومَ القيامة؛ ليوفّيهم أجورهم ويزيدهم من فضله؛ من جاء بالحسنةِ فله عشرُ أمثالها؛ فالجزاءُ أوفى وأكملُ من العمل بفضلِ الله؛ فمن عمل صالحًا وُفّي جزاءه مضاعفًا، ومن أساء جُوزي بمثله عدلًا؛ فاجعل العملَ الصالحَ ثقةً بالجزاءِ الأوفى دأبك."}},{"n":42,"reflection":{"text":"«وأن إلى ربك المنتهى»، وأنّ إلى ربّك وحده المنتهى والمرجعُ والمصير؛ ففي هذا تقريرُ أنّ المرجعَ إلى الله؛ فاعلم أنّ مصيرك ومنتهاك إلى الله، فاستعدّ للقائه، فمن كان منتهاه إلى الله فليعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للقاءِ الله، وإدراكُ أنّ المنتهى إليه."},"action":{"text":"تأمّل أنّ المنتهى إلى الله: وأنّ إلى ربّك، يا محمدُ، وحده المنتهى والمرجعُ والمصيرُ والمآل؛ فإليه تنتهي الأمورُ كلُّها، وإليه يرجع الخلقُ للحسابِ والجزاء «وأن إلى ربك المنتهى»؛ ففي هذا تقريرُ أنّ المنتهى والمرجعَ إلى الله وحده؛ فإليه تصير الأمورُ وترجع الخلائق؛ فاعلم أنت أنّ مصيرك ومنتهاك ومرجعك إلى الله وحده؛ وأنّ إلى ربّك المنتهى؛ إنّ إلينا إيابهم ثم إنّ علينا حسابهم؛ وإلى الله تُرجَع الأمور؛ وإليه المصير؛ فاستعدّ للقاءِ الله بالإيمانِ والعملِ الصالح؛ فمن كان منتهاه ومرجعه إلى الله فليعمل له وليستعدّ للقائه؛ فمن استعدّ للقاءِ الله فاز، ومن غفل عنه خسر؛ فاجعل الاستعدادَ للقاءِ الله وإدراكَ أنّ المنتهى إليه دأبك."}}]},{"title":"أفعالُ الله وحده: الإحياءُ والإماتةُ والغنى والربوبية","range":[43,49],"theme":"تقريرُ أنّ الله وحده أضحك وأبكى وأمات وأحيا، وخلق الزوجين الذكرَ والأنثى من نطفةٍ إذا تُمنى، وأنّ عليه النشأةَ الأخرى، وأنه أغنى وأقنى وهو ربُّ الشِّعرى","verses":[{"n":43,"reflection":{"text":"«وأنه هو أضحك وأبكى»، وأنّ الله وحده هو الذي أضحك وأبكى (خلق أسبابَ الفرحِ والحزن)؛ ففي هذا تقريرُ أنّ أفعالَ العبادِ ومشاعرهم بخلقِ الله؛ فاعلم أنّ الضحكَ والبكاءَ والفرحَ والحزنَ كلَّها بيدِ الله، فسلّم لتدبيره، فما يصيبك من فرحٍ أو حزنٍ بقدرِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لتدبيرِ الله، وإدراكُ أنّ الفرحَ والحزنَ بيده."},"action":{"text":"تأمّل أنّ الأفعالَ بخلقِ الله: وأنّ الله وحده هو الذي أضحك من شاء وأبكى من شاء؛ فهو الذي خلق الضحكَ والبكاء، وأسبابَ الفرحِ والحزنِ والسرورِ والغمّ؛ فالكلُّ بتقديره وخلقه «وأنه هو أضحك وأبكى»؛ ففي هذا تقريرُ أنّ أفعالَ العبادِ ومشاعرهم، كالضحكِ والبكاءِ والفرحِ والحزن، بخلقِ الله وتقديره؛ فهو خالقُ ذلك كلِّه؛ فاعلم أنت أنّ الضحكَ والبكاءَ والفرحَ والحزنَ كلَّها بيدِ الله وخلقه وتقديره؛ فما من فرحٍ ولا حزنٍ إلا بقدرِ الله؛ وأنه هو أضحك وأبكى؛ فسلّم لتدبيرِ الله وقدره فيما يصيبك؛ ما أصاب من مصيبةٍ في الأرضِ ولا في أنفسكم إلا في كتاب؛ لكيلا تأسوا على ما فاتكم ولا تفرحوا بما آتاكم؛ فما يصيبك من فرحٍ أو حزنٍ بقدرِ الله وخلقه؛ فمن سلّم لتدبيرِ الله اطمأنّ، ومن اعترض تعب؛ فاجعل التسليمَ لتدبيرِ الله وإدراكَ أنّ الفرحَ والحزنَ بيده دأبك."}},{"n":44,"reflection":{"text":"«وأنه هو أمات وأحيا»، وأنّ الله وحده هو الذي أمات وأحيا؛ ففي هذا تقريرُ أنّ الإحياءَ والإماتةَ بيدِ الله؛ فوحّد الله المحييَ المميت، واعلم أنّ حياتك وموتك بيده، فمن بيده الحياةُ والموتُ يستحقّ العبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله المحييِ المميت، وإدراكُ أنّ الحياةَ والموتَ بيده."},"action":{"text":"تأمّل أنّ الإحياءَ والإماتةَ بيدِ الله: وأنّ الله وحده هو الذي أمات الأحياءَ عند انقضاءِ آجالهم، وأحيا الموتى والأمواتَ بالخلقِ والبعث؛ فبيده الإحياءُ والإماتة، لا يقدر عليهما غيره «وأنه هو أمات وأحيا»؛ ففي هذا تقريرُ أنّ الإحياءَ والإماتةَ بيدِ الله وحده؛ فهو المحيي المميت؛ فوحّد أنت الله المحييَ المميت؛ واعلم أنّ حياتك وموتك بيده وحده؛ الله يتوفّى الأنفسَ حين موتها؛ هو يحيي ويميت؛ كيف تكفرون بالله وكنتم أمواتًا فأحياكم ثم يميتكم ثم يحييكم؛ الذي خلق الموتَ والحياةَ ليبلوكم؛ فمن بيده الحياةُ والموتُ هو المستحقُّ للعبادةِ وحده؛ فوحّده في العبادةِ كما تفرّد بالإحياءِ والإماتة؛ فمن وحّد الله المحييَ المميتَ نجا، ومن أشرك هلك؛ فاجعل توحيدَ الله المحييِ المميتِ دأبك."}},{"n":45,"reflection":{"text":"«وأنه خلق الزوجين الذكر والأنثى»، وأنّ الله خلق الزوجين الذكرَ والأنثى؛ ففي هذا بيانُ قدرةِ الله في خلقِ الزوجين؛ فتأمّل خلقَ الله للذكرِ والأنثى، فمن خلقهما قادرٌ على البعث، فعظّم قدرةَ الله واعتبر بخلقه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ قدرةِ الله في خلقِ الزوجين، والاعتبارُ بها."},"action":{"text":"تأمّل خلقَ الزوجين: وأنّ الله وحده خلق الزوجين، الذكرَ والأنثى، من الإنسِ والحيوانِ وسائرِ الأحياء؛ فهو خالقُ النوعين ومقدّرهما «وأنه خلق الزوجين الذكر والأنثى»؛ ففي هذا بيانُ قدرةِ الله في خلقِ الزوجين الذكرِ والأنثى، ودلالتِه على وحدانيته وقدرته؛ فخلقهما بحكمته لبقاءِ النسل؛ فتأمّل أنت خلقَ الله للذكرِ والأنثى من نطفةٍ واحدة؛ ومن كلِّ شيءٍ خلقنا زوجين لعلّكم تذكّرون؛ وأنه خلق الزوجين الذكرَ والأنثى من نطفةٍ إذا تُمنى؛ سبحان الذي خلق الأزواجَ كلَّها؛ فمن خلق الزوجين من نطفةٍ قادرٌ على البعثِ والإعادة؛ فعظّم أنت قدرةَ الله في خلقِ الزوجين؛ فمن تفكّر في خلقِ الله أيقن بقدرته وبالبعث؛ فاجعل تعظيمَ قدرةِ الله في خلقِ الزوجين والاعتبارَ بها دأبك."}},{"n":46,"reflection":{"text":"«من نطفة إذا تمنى»: خلقهما من نطفةٍ (منيّ) إذا تُدفَق في الرحم؛ ففي هذا بيانُ أصلِ خلقِ الإنسان؛ فتأمّل خلقك من نطفةٍ حقيرة، فكيف تتكبّر؟ فتواضع لله واعتبر بأصلِ خلقك، فمن خُلِق من نطفةٍ لا يليق به الكبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ لله والاعتبارُ بأصلِ الخلق، وتركُ الكبر."},"action":{"text":"تأمّل أصلَ الخلق: خلق الله الزوجين الذكرَ والأنثى من نطفةٍ، أي من منيٍّ ضعيفٍ حقير، إذا تُمنى، أي إذا تُدفَق وتُصَبُّ في الرحم؛ فمن هذا الأصلِ الحقيرِ خلق الله الإنسان «من نطفة إذا تمنى»؛ ففي هذا بيانُ أصلِ خلقِ الإنسانِ من نطفةٍ ضعيفةٍ حقيرة؛ فأصله ماءٌ مهين؛ فتأمّل أنت خلقك من نطفةٍ حقيرة، فكيف تتكبّر وتتعاظم؟ فتواضع لله واعتبر بأصلِ خلقك الحقير؛ ألم نخلقكم من ماءٍ مهين؛ خُلِق من ماءٍ دافق؛ فلينظرِ الإنسانُ ممَّ خُلِق؛ قُتِل الإنسانُ ما أكفره، من أيِّ شيءٍ خلقه، من نطفةٍ خلقه فقدّره؛ فمن خُلِق من نطفةٍ لا يليق به الكبرُ والعظمة؛ فمن تواضع لله واعتبر بأصله نجا، ومن تكبّر هلك؛ فاجعل التواضعَ لله والاعتبارَ بأصلِ خلقك وتركَ الكبرِ دأبك."}},{"n":47,"reflection":{"text":"«وأن عليه النشأة الأخرى»، وأنّ على الله النشأةَ الأخرى (البعثَ بعد الموت)؛ ففي هذا تقريرُ البعث؛ فأيقن بالبعثِ الذي تكفّل الله به، فمن أنشأك أوّلًا قادرٌ على إعادتك، فاستعدّ للنشأةِ الأخرى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعث، والاستعدادُ للنشأةِ الأخرى."},"action":{"text":"تأمّل تقريرَ البعث: وأنّ على الله النشأةَ الأخرى، وهي البعثُ والإعادةُ بعد الموتِ يومَ القيامة؛ فكما أنشأكم أوّلَ مرّة، عليه أن ينشئكم نشأةً أخرى للحسابِ والجزاء «وأن عليه النشأة الأخرى»؛ ففي هذا تقريرُ البعثِ والنشأةِ الأخرى، وأنّ الله تكفّل بها؛ فالذي أنشأ الخلقَ أوّلًا قادرٌ على إعادته؛ فأيقن أنت بالبعثِ والنشأةِ الأخرى التي تكفّل الله بها؛ فمن أنشأك من نطفةٍ أوّلًا قادرٌ على إعادتك بعد الموت؛ ولقد علمتم النشأةَ الأولى فلولا تذكّرون؛ كما بدأنا أوّلَ خلقٍ نعيده؛ وهو الذي يبدأ الخلقَ ثم يعيده وهو أهونُ عليه؛ فاستعدّ للنشأةِ الأخرى والبعثِ بالإيمانِ والعملِ الصالح؛ فمن أيقن بالبعثِ واستعدّ له نجا، ومن أنكره أو غفل عنه خسر؛ فاجعل اليقينَ بالبعثِ والاستعدادَ للنشأةِ الأخرى دأبك."}},{"n":48,"reflection":{"text":"«وأنه هو أغنى وأقنى»، وأنّ الله وحده هو الذي أغنى العبادَ وأقناهم (أعطاهم القِنيةَ والمال)؛ ففي هذا تقريرُ أنّ الغنى من الله؛ فاعلم أنّ غناك ورزقك من الله، فاشكره على غناه واطلب منه، فمن أغناك يستحقّ الشكرَ والعبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ الله على الغنى، وإدراكُ أنّ الرزقَ منه وحده."},"action":{"text":"تأمّل أنّ الغنى من الله: وأنّ الله وحده هو الذي أغنى العبادَ بما أعطاهم من الأموال، وأقنى، أي جعل لهم القِنيةَ والأصولَ الثابتةَ من المال، أو أرضاهم بما أعطاهم وأقناهم؛ فالغنى والرزقُ منه وحده «وأنه هو أغنى وأقنى»؛ ففي هذا تقريرُ أنّ الغنى والرزقَ والقِنيةَ من الله وحده؛ فهو المُغني المُقني؛ فاعلم أنت أنّ غناك ورزقك ومالك من الله وحده؛ ووجدك عائلًا فأغنى؛ والله فضّل بعضكم على بعضٍ في الرزق؛ إنّ الله هو الرزّاقُ ذو القوّةِ المتين؛ فاشكر الله على غناه ونعمته وعطائه؛ ولا تنسبِ الغنى إلى حولك وقوّتك؛ إنما أوتيته على علمٍ عندي؛ فمن أغناك وأعطاك يستحقّ الشكرَ والعبادةَ وحده؛ فاطلب الرزقَ والغنى من الله وحده؛ فمن شكر الله على غناه زاده، ومن كفره سلبه؛ فاجعل شكرَ الله على الغنى وإدراكَ أنّ الرزقَ منه دأبك."}},{"n":49,"reflection":{"text":"«وأنه هو رب الشعرى»، وأنّ الله هو ربُّ الشِّعرى (نجمٍ كانت طائفةٌ تعبده)؛ ففي هذا إبطالُ عبادةِ النجومِ وتقريرُ ربوبيةِ الله لها؛ فوحّد الله ربَّ النجومِ ولا تعبد نجمًا، فالنجومُ مخلوقةٌ مربوبةٌ لله، فاعبد ربّها لا إيّاها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله ربِّ النجوم، وتركُ عبادةِ المخلوقات."},"action":{"text":"تأمّل إبطالَ عبادةِ النجوم: وأنّ الله وحده هو ربُّ الشِّعرى، وهو نجمٌ مضيءٌ كانت خزاعةُ وبعضُ العربِ تعبده من دونِ الله؛ فبيّن أنّ الله ربُّه وخالقه ومدبّره، فكيف يُعبَد مع الله؟ «وأنه هو رب الشعرى»؛ ففي هذا إبطالٌ لعبادةِ النجومِ والكواكب، وتقريرٌ أنّ الله ربُّها وخالقها؛ فالنجمُ الذي عبدوه مخلوقٌ مربوبٌ لله؛ فاعلم أنت أنّ الله وحده ربُّ النجومِ والكواكبِ وخالقها ومدبّرها؛ فوحّد الله ربَّ النجومِ ولا تعبد نجمًا ولا كوكبًا؛ فالنجومُ مخلوقةٌ مربوبةٌ مسخّرة؛ ومن آياته الليلُ والنهارُ والشمسُ والقمر، لا تسجدوا للشمسِ ولا للقمرِ واسجدوا لله الذي خلقهنّ؛ فاعبد ربَّ النجومِ لا النجوم؛ فمن وحّد الله ربَّ كلِّ شيءٍ وعبده نجا، ومن عبد المخلوقاتِ هلك؛ فاجعل توحيدَ الله ربِّ النجومِ وتركَ عبادةِ المخلوقاتِ دأبك."}}]},{"title":"إهلاكُ الأمم، والأمرُ بالسجودِ والعبادة","range":[50,62],"theme":"إهلاكُ عادٍ الأولى وثمودَ فما أبقى وقومِ نوحٍ الأظلمِ الأطغى والمؤتفكةِ فغشّاها ما غشّى، والإنكارُ على من يتمارى في نعمِ الله، وأنّ النبيَّ نذيرٌ من النذرِ الأولى وقد أزفت الآزفةُ ليس لها من دونِ الله كاشفة، وتوبيخُهم على العجبِ والضحكِ واللهوِ، وختامُ السورةِ بالأمرِ بالسجودِ لله والعبادة (أوّلُ سجدةِ تلاوة)","verses":[{"n":50,"reflection":{"text":"«وأنه أهلك عادا الأولى»، وأنّ الله أهلك عادًا الأولى (قومَ هود)؛ ففي هذا التذكيرُ بإهلاكِ عاد؛ فاعتبر بإهلاكِ عادٍ بكفرهم، فالكفرُ سببُ الهلاك، فاحذر أن يصيبك ما أصابهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بإهلاكِ عاد، والحذرُ من الكفرِ الموجبِ للهلاك."},"action":{"text":"تأمّل إهلاكَ عاد: وأنّ الله وحده هو الذي أهلك عادًا الأولى، وهم قومُ هودٍ الأقدمون، أهلكهم الله بالريحِ الصرصرِ العاتيةِ لكفرهم وتكذيبهم «وأنه أهلك عادا الأولى»؛ ففي هذا التذكيرُ بإهلاكِ عادٍ الأولى بكفرهم، تخويفًا للمشركين؛ فأهلكهم الله رغمَ قوّتهم؛ فاعتبر أنت بإهلاكِ عادٍ بكفرهم واستكبارهم؛ فأمّا عادٌ فأُهلِكوا بريحٍ صرصرٍ عاتية؛ وأمّا عادٌ فاستكبروا في الأرضِ بغيرِ الحقّ؛ فالكفرُ والاستكبارُ سببُ الهلاك؛ فاحذر أن يصيبك ما أصاب عادًا من التكذيبِ والكفر؛ فمن اتّعظ بإهلاكِ عادٍ نجا، ومن سلك سبيلهم هلك؛ فاجعل الاعتبارَ بإهلاكِ عادٍ والحذرَ من الكفرِ دأبك."}},{"n":51,"reflection":{"text":"«وثمود فما أبقى»، وأهلك ثمودَ فما أبقى منهم أحدًا؛ ففي هذا التذكيرُ بإهلاكِ ثمود؛ فاعتبر بإهلاكِ ثمودَ بكفرهم، فما أبقى الله منهم أحدًا، فالتكذيبُ سببُ الاستئصال، فاحذره.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بإهلاكِ ثمود، والحذرُ من التكذيبِ الموجبِ للاستئصال."},"action":{"text":"تأمّل إهلاكَ ثمود: وأهلك الله ثمودَ، قومَ صالح، بالصيحةِ والرجفةِ لعقرهم الناقةَ وكفرهم؛ فما أبقى منهم أحدًا، بل استأصلهم جميعًا «وثمود فما أبقى»؛ ففي هذا التذكيرُ بإهلاكِ ثمودَ واستئصالهم بكفرهم؛ فأهلكهم الله فلم يبقَ منهم أحد؛ فاعتبر أنت بإهلاكِ ثمودَ واستئصالهم بتكذيبهم وكفرهم؛ فأمّا ثمودُ فأُهلِكوا بالطاغية؛ فأخذتهم الصاعقةُ وهم ينظرون؛ فكذّبوه فعقروها فدمدم عليهم ربّهم بذنبهم فسوّاها؛ فالتكذيبُ والكفرُ سببُ الاستئصالِ والهلاك؛ فاحذر أن يصيبك ما أصاب ثمودَ من التكذيبِ والكفر؛ فمن اتّعظ بإهلاكِ ثمودَ نجا، ومن سلك سبيلهم هلك؛ فاجعل الاعتبارَ بإهلاكِ ثمودَ والحذرَ من التكذيبِ دأبك."}},{"n":52,"reflection":{"text":"«وقوم نوح من قبل إنهم كانوا هم أظلم وأطغى»، وأهلك قومَ نوحٍ من قبل، إنهم كانوا أظلمَ وأطغى؛ ففي هذا التذكيرُ بإهلاكِ قومِ نوح؛ فاعتبر بإهلاكِ الأظلمِ الأطغى، فالظلمُ والطغيانُ سببُ الهلاك، فاجتنبهما لتنجو.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الظلمِ والطغيان، والاعتبارُ بإهلاكِ قومِ نوح."},"action":{"text":"تأمّل إهلاكَ قومِ نوح: وأهلك الله قومَ نوحٍ من قبلِ عادٍ وثمودَ بالطوفان؛ إنهم كانوا هم أظلمَ وأطغى من غيرهم، لطولِ مدّةِ دعوةِ نوحٍ لهم (٩٥٠ سنة) وإصرارهم على الكفرِ والطغيان «وقوم نوح من قبل إنهم كانوا هم أظلم وأطغى»؛ ففي هذا التذكيرُ بإهلاكِ قومِ نوحٍ لظلمهم وطغيانهم؛ فأهلكهم الله بالغرقِ لطولِ إصرارهم؛ فاعتبر أنت بإهلاكِ قومِ نوحٍ الأظلمِ الأطغى؛ وقومَ نوحٍ لمّا كذّبوا الرسلَ أغرقناهم؛ فأخذهم الطوفانُ وهم ظالمون؛ فالظلمُ والطغيانُ والإصرارُ على الكفرِ سببُ الهلاك؛ فاجتنب أنت الظلمَ والطغيانَ لتنجو؛ فمن اجتنب الظلمَ والطغيانَ نجا، ومن ظلم وطغى هلك؛ فاجعل اجتنابَ الظلمِ والطغيانِ والاعتبارَ بإهلاكِ قومِ نوحٍ دأبك."}},{"n":53,"reflection":{"text":"«والمؤتفكة أهوى»، والمؤتفكةَ (قرى قومِ لوط) أسقطها الله وقلبها؛ ففي هذا التذكيرُ بإهلاكِ قومِ لوط؛ فاعتبر بإهلاكِ قومِ لوطٍ بفاحشتهم، فالفاحشةُ سببُ الهلاك، فاجتنبها لتنجو.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ الفواحش، والاعتبارُ بإهلاكِ قومِ لوط."},"action":{"text":"تأمّل إهلاكَ قومِ لوط: والمؤتفكةَ، وهي قرى قومِ لوطٍ التي ائتفكت أي انقلبت بأهلها، أهوى الله بها، أي رفعها ثم أسقطها وقلب عاليها سافلها، وأمطر عليها الحجارة، عقوبةً لفاحشتهم وكفرهم «والمؤتفكة أهوى»؛ ففي هذا التذكيرُ بإهلاكِ قومِ لوطٍ بقلبِ قراهم وإمطارِ الحجارة، جزاءَ فاحشتهم؛ فأهلكهم الله بفاحشتهم؛ فاعتبر أنت بإهلاكِ قومِ لوطٍ بفاحشتهم؛ فجعلنا عاليها سافلها وأمطرنا عليهم حجارةً من سِجّيل؛ والمؤتفكاتِ أتتهم رسلهم بالبيّنات؛ فالفاحشةُ والكفرُ سببُ الهلاكِ والدمار؛ فاجتنب أنت الفواحشَ ما ظهر منها وما بطن؛ فمن اجتنب الفواحشَ نجا، ومن ارتكبها استحقّ الهلاك؛ فاجعل اجتنابَ الفواحشِ والاعتبارَ بإهلاكِ قومِ لوطٍ دأبك."}},{"n":54,"reflection":{"text":"«فغشاها ما غشى»: فغطّاها وأصابها من العذابِ (الحجارةِ) ما غطّاها؛ ففي هذا تعظيمُ عذابِ قومِ لوط؛ فاحذر عذابَ الله الذي غشي قومَ لوط، فعذابُ الله شديد، فاتّق الله واجتنب أسبابَ سخطه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ الله الشديد، واجتنابُ أسبابِ سخطه."},"action":{"text":"تأمّل تعظيمَ عذابِ قومِ لوط: فغشّى الله المؤتفكةَ وغطّاها وأصابها من العذابِ والحجارةِ ما غشّاها؛ فأبهم ما غشّاها تعظيمًا وتهويلًا لعذابها «فغشاها ما غشى»؛ ففي هذا تعظيمُ عذابِ قومِ لوطٍ الذي غشّاهم؛ فأبهمه تفخيمًا لهوله وشدّته؛ فأصابهم عذابٌ عظيمٌ لا يُوصَف؛ فاحذر أنت عذابَ الله الشديدَ الذي غشي قومَ لوطٍ وأمثالهم؛ فعذابُ الله شديدٌ لمن استحقّه؛ إنّ بطشَ ربّك لشديد؛ فأمطرنا عليهم حجارةً من سِجّيل؛ فاتّق الله واجتنب أسبابَ سخطه وعذابه من الكفرِ والفواحشِ والمعاصي؛ فمن اتّقى الله وحذر عذابه نجا، ومن أمنه وارتكب أسبابه هلك؛ فاجعل الحذرَ من عذابِ الله واجتنابَ أسبابِ سخطه دأبك."}},{"n":55,"reflection":{"text":"«فبأي آلاء ربك تتمارى»: فبأيِّ نعمِ ربّك، أيها الإنسان، تشكّ وتجادل؟ ففي هذا إنكارٌ على من يشكّ في نعمِ الله؛ فاعترف بنعمِ الله ولا تشكّ فيها، فنعمُ الله ظاهرةٌ لا تُنكَر، فاشكرها ولا تجادل فيها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعترافُ بنعمِ الله وشكرُها، وتركُ الشكِّ والمجادلة."},"action":{"text":"تأمّل الإنكارَ على المتماري: فبأيِّ آلاءِ ونعمِ ربّك، أيها الإنسانُ المكذّب، تتمارى وتشكّ وتجادل؟ أبنعمِه التي لا تُحصى، أم بآياته وحججه؟ فنعمُ الله وآياته أوضحُ من أن يُشَكَّ فيها «فبأي آلاء ربك تتمارى»؛ ففي هذا إنكارٌ وتوبيخٌ لمن يشكّ ويجادل في نعمِ الله وآياته الظاهرة؛ فنعمُ الله كثيرةٌ ظاهرة، فكيف يُشَكُّ فيها؟ فاعترف أنت بنعمِ الله ولا تشكّ فيها ولا تجادل؛ وإن تعدّوا نعمةَ الله لا تحصوها؛ وما بكم من نعمةٍ فمن الله؛ وأسبغ عليكم نعمه ظاهرةً وباطنة؛ فنعمُ الله ظاهرةٌ لا تُنكَر ولا يُشَكُّ فيها؛ فاشكرها ولا تجادل فيها ولا تكفرها؛ فمن اعترف بنعمِ الله وشكرها زاده، ومن شكّ فيها أو كفرها سلبها؛ فاجعل الاعترافَ بنعمِ الله وشكرَها وتركَ الشكِّ دأبك."}},{"n":56,"reflection":{"text":"«هذا نذير من النذر الأولى»: هذا (محمدٌ) نذيرٌ من جنسِ النذرِ الأولى (الرسلِ السابقين)؛ ففي هذا بيانُ أنّ النبيَّ نذيرٌ كالرسلِ قبله؛ فاقبل نذارةَ النبيِّ كما وجب قبولُ نذارةِ الرسل، فالنبيُّ منذرٌ كسائرِ الرسل، فاتّعظ بنذارته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ نذارةِ النبيِّ والاتّعاظُ بها، كنذارةِ الرسل."},"action":{"text":"تأمّل أنّ النبيَّ نذيرٌ كالرسل: هذا الرسولُ محمدٌ ﷺ نذيرٌ منذرٌ من جنسِ النذرِ الأولى، أي الرسلِ السابقين الذين أنذروا أقوامهم؛ فهو على منهاجهم في الإنذارِ والدعوةِ إلى التوحيد «هذا نذير من النذر الأولى»؛ ففي هذا بيانُ أنّ النبيَّ محمدًا ﷺ نذيرٌ كسائرِ الرسلِ قبله، ليس بدعًا منهم؛ فدعوته دعوتهم، وإنذاره إنذارهم؛ فاقبل أنت نذارةَ النبيِّ ﷺ كما وجب قبولُ نذارةِ الرسلِ قبله؛ قل ما كنت بدعًا من الرسل؛ وما أرسلناك إلا مبشّرًا ونذيرًا؛ إنا أرسلناك شاهدًا ومبشّرًا ونذيرًا؛ فالنبيُّ منذرٌ كسائرِ الرسل، على منهاجهم؛ فاتّعظ بنذارته واستعدّ لما أنذر منه؛ فمن قبل نذارةَ النبيِّ واتّعظ بها نجا، ومن أعرض عنها هلك؛ فاجعل قبولَ نذارةِ النبيِّ والاتّعاظَ بها دأبك."}},{"n":57,"reflection":{"text":"«أزفت الآزفة»: قربت القيامةُ ودنت الساعة؛ ففي هذا بيانُ قربِ الساعة؛ فاستعدّ للساعةِ القريبة، فالقيامةُ دانيةٌ قريبة، فبادر بالعملِ قبل مجيئها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للساعةِ القريبة، والمبادرةُ بالعمل."},"action":{"text":"تأمّل قربَ الساعة: أزفت الآزفة، أي قربت ودنت القيامةُ والساعةُ التي وُعِدتم بها؛ فهي قريبةٌ آتيةٌ لا محالة «أزفت الآزفة»؛ ففي هذا بيانُ قربِ الساعةِ ودنوّها؛ فالقيامةُ قريبةٌ وإن استبعدها الناس؛ فاستعدّ أنت للساعةِ القريبةِ الدانية؛ اقتربتِ الساعةُ وانشقّ القمر؛ اقترب للناسِ حسابهم وهم في غفلةٍ معرضون؛ أتى أمرُ الله فلا تستعجلوه؛ وما أمرُ الساعةِ إلا كلمحِ البصرِ أو هو أقرب؛ فالقيامةُ دانيةٌ قريبةٌ آتية؛ فبادر بالعملِ الصالحِ والتوبةِ قبل مجيئها؛ فمن استعدّ للساعةِ بالعملِ نجا، ومن غفل عنها خسر؛ فاجعل الاستعدادَ للساعةِ والمبادرةَ بالعملِ دأبك."}},{"n":58,"reflection":{"text":"«ليس لها من دون الله كاشفة»: ليس للساعةِ (أو لأهوالها) من دونِ الله كاشفةٌ تكشفها أو تدفعها؛ ففي هذا بيانُ أنه لا رادَّ لأمرِ الله؛ فاعلم أنه لا يدفع أهوالَ القيامةِ إلا الله، فالجأ إليه واستعدّ، فلا مانعَ لما قدّره الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الالتجاءُ إلى الله والاستعدادُ، وإدراكُ أنه لا رادَّ لأمره."},"action":{"text":"تأمّل أنه لا رادَّ لأمرِ الله: ليس للساعةِ وأهوالها من دونِ الله كاشفةٌ تكشف وقتها فتُظهِره، أو تدفع أهوالها وتزيلها؛ فلا يعلم وقتها ولا يدفع أهوالها إلا الله «ليس لها من دون الله كاشفة»؛ ففي هذا بيانُ أنه لا أحدَ يكشف الساعةَ أو يدفع أهوالها إلا الله؛ فأمرها بيدِ الله وحده؛ فاعلم أنت أنه لا يدفع أهوالَ القيامةِ ولا يكشفها إلا الله؛ فلا مانعَ لما قدّره ولا رادَّ لأمره؛ يسألونك عن الساعةِ أيّان مرساها، قل إنما علمها عند ربي لا يجلّيها لوقتها إلا هو؛ ما لها من دونِ الله كاشفة؛ فالجأ أنت إلى الله واستعدّ لأهوالِ القيامة؛ فلا ملجأ من الله إلا إليه؛ ففرّوا إلى الله؛ فمن التجأ إلى الله واستعدّ نجا، ومن غفل خسر؛ فاجعل الالتجاءَ إلى الله والاستعدادَ لأهوالِ القيامةِ دأبك."}},{"n":59,"reflection":{"text":"«أفمن هذا الحديث تعجبون»: أفمن هذا القرآنِ (أو خبرِ القيامة) تعجبون منكرين؟ ففي هذا إنكارٌ على تعجّبهم من الحق؛ فلا تعجب من الحقِّ إنكارًا، بل اقبله وتدبّره، فالعجبُ من الحقِّ إنكارًا من صفاتِ المكذّبين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ وتدبّرُه، وتركُ التعجّبِ منه إنكارًا."},"action":{"text":"تأمّل الإنكارَ على تعجّبهم: أفمن هذا الحديثِ، وهو القرآنُ، أو خبرُ البعثِ والقيامة، تعجبون منكرين مكذّبين مستهزئين؟ إنكارٌ عليهم في تعجّبهم من الحقِّ الواضح «أفمن هذا الحديث تعجبون»؛ ففي هذا إنكارٌ على المشركين في تعجّبهم من القرآنِ وخبرِ القيامةِ إنكارًا وتكذيبًا؛ فتعجّبوا من الحقِّ كأنه مستحيل؛ فلا تعجب أنت من الحقِّ إنكارًا واستبعادًا؛ بل اقبله وتدبّره وآمن به؛ بل عجبوا أن جاءهم منذرٌ منهم؛ بل عجبت ويسخرون، وإذا ذُكِّروا لا يذكرون؛ فالعجبُ من الحقِّ إنكارًا واستهزاءً من صفاتِ المكذّبين؛ فمن قبل الحقَّ وتدبّره اهتدى، ومن تعجّب منه إنكارًا ضلّ؛ فاجعل قبولَ الحقِّ وتدبّرَه وتركَ التعجّبِ منه دأبك."}},{"n":60,"reflection":{"text":"«وتضحكون ولا تبكون»، وتضحكون استهزاءً ولا تبكون خوفًا واتّعاظًا؟ ففي هذا إنكارٌ على ضحكهم واستهزائهم؛ فاحذر الضحكَ والاستهزاءَ بالحق، بل ابكِ خوفًا من الله واتّعاظًا، فالبكاءُ من خشيةِ الله من صفاتِ المؤمنين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"البكاءُ من خشيةِ الله والاتّعاظُ، وتركُ الضحكِ والاستهزاء."},"action":{"text":"تأمّل الإنكارَ على ضحكهم: وتضحكون، أيها المشركون، من هذا القرآنِ وخبرِ القيامةِ استهزاءً وسخرية؛ ولا تبكون خوفًا من الله واتّعاظًا بما فيه من الوعيد؟ إنكارٌ عليهم في ضحكهم وعدمِ بكائهم «وتضحكون ولا تبكون»؛ ففي هذا إنكارٌ على المشركين في ضحكهم واستهزائهم بالحق، وعدمِ بكائهم واتّعاظهم؛ فضحكوا حيث ينبغي البكاء؛ فاحذر أنت الضحكَ والاستهزاءَ بالحقِّ وآياتِ الله؛ بل ابكِ خوفًا من الله واتّعاظًا بوعيده؛ فليضحكوا قليلًا وليبكوا كثيرًا جزاءً بما كانوا يكسبون؛ وإذا تُليت عليهم آياتُ الرحمنِ خرّوا سجّدًا وبكيًّا؛ تفيض من الدمعِ ممّا عرفوا من الحق؛ فالبكاءُ من خشيةِ الله والاتّعاظِ من صفاتِ المؤمنين، والضحكُ والاستهزاءُ من صفاتِ المكذّبين؛ فمن بكى من خشيةِ الله واتّعظ نجا، ومن ضحك واستهزأ خسر؛ فاجعل البكاءَ من خشيةِ الله والاتّعاظَ وتركَ الاستهزاءِ دأبك."}},{"n":61,"reflection":{"text":"«وأنتم سامدون»، وأنتم لاهون غافلون معرضون مستكبرون؛ ففي هذا ذمُّ اللهوِ والغفلةِ والإعراض؛ فاحذر اللهوَ والغفلةَ عن الحقِّ والاستكبار، فاشتغل بالحقِّ والجدّ، فاللهوُ والغفلةُ من صفاتِ المعرضين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجدُّ في الحقِّ وتركُ اللهوِ والغفلةِ والاستكبار."},"action":{"text":"تأمّل ذمَّ اللهوِ والغفلة: وأنتم سامدون، أي لاهون غافلون معرضون، مستكبرون رافعون رؤوسكم عن سماعِ الحقِّ والانقيادِ له؛ فجمعتم بين الضحكِ واللهوِ والغفلةِ والاستكبار «وأنتم سامدون»؛ ففي هذا ذمُّ المشركين على لهوهم وغفلتهم وإعراضهم واستكبارهم عن الحق؛ فلهوا وغفلوا واستكبروا؛ فاحذر أنت اللهوَ والغفلةَ عن الحقِّ والقرآن، والاستكبارَ عن الانقيادِ له؛ فاشتغل بالحقِّ والجدِّ في العملِ للآخرة؛ ألهاكم التكاثر؛ في غمرةٍ ساهون؛ وذرِ الذين اتّخذوا دينهم لعبًا ولهوًا وغرّتهم الحياةُ الدنيا؛ فاللهوُ والغفلةُ والاستكبارُ من صفاتِ المعرضين المكذّبين؛ فمن جدَّ في الحقِّ وترك اللهوَ نجا، ومن لها وغفل واستكبر خسر؛ فاجعل الجدَّ في الحقِّ وتركَ اللهوِ والغفلةِ والاستكبارِ دأبك."}},{"n":62,"reflection":{"text":"«فاسجدوا لله واعبدوا»: فاسجدوا لله وحده واعبدوه مخلصين؛ ففي هذا الأمرُ بالسجودِ والعبادةِ لله (وهي أوّلُ سجدةِ تلاوة)؛ فاسجد لله واعبده وحده مخلصًا، فالسجودُ والعبادةُ لله وحده غايةُ الخلق، فأخلص عبادتك له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"السجودُ والعبادةُ لله وحده بإخلاص، وتحقيقُ الغايةِ من الخلق."},"action":{"text":"تأمّل الأمرَ بالسجودِ والعبادة: فاسجدوا لله وحده، أيها الناس، واعبدوه مخلصين له الدين؛ فلمّا ذُكِّروا بآياتِ الله ونعمه وقدرته، خُتِمت السورةُ بالأمرِ بالسجودِ والعبادةِ له وحده؛ (وهنا أوّلُ سجدةِ تلاوةٍ في المصحف) «فاسجدوا لله واعبدوا»؛ ففي هذا الأمرُ بالسجودِ لله والعبادةِ له وحده مخلصين، وهو غايةُ ما دعت إليه السورة؛ فبعد إبطالِ الشركِ وتقريرِ التوحيدِ وأفعالِ الله، أمر بالسجودِ والعبادةِ له؛ فاسجد أنت لله وحده، واعبده مخلصًا له الدين؛ واسجد واقترب؛ يا أيها الذين آمنوا اركعوا واسجدوا واعبدوا ربّكم؛ وما خلقت الجنَّ والإنسَ إلا ليعبدون؛ فاعبدوا الله ولا تشركوا به شيئًا؛ فالسجودُ والعبادةُ لله وحده غايةُ الخلقِ وسرُّ الوجود؛ فأخلص عبادتك وسجودك لله وحده؛ فمن سجد لله وعبده مخلصًا سعد، ومن استكبر عن عبادته شقي؛ فاجعل السجودَ والعبادةَ لله وحده بإخلاصٍ دأبك."}}]}],"coverage":{"covered":62,"total":62}};
